window.QCM_DATA={"matieres":{"cg":"Culture générale","ma":"Mathématiques et logique"},"questions":[{"id":1,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel chef gaulois dirige la résistance contre Jules César avant de capituler à Alésia en 52 av. J.-C. ?","c":["Vercingétorix","Brennus","Ambiorix","Commios"],"a":0,"e":"Vercingétorix, chef arverne, se rend à César après le siège d'Alésia (52 av. J.-C.). Ambiorix était un chef éburon, Brennus a pris Rome vers 390 av. J.-C."},{"id":2,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi franc se fait baptiser à Reims par l'évêque Remi, vers 496-499 ?","c":["Dagobert Ier","Clovis","Childéric Ier","Clotaire Ier"],"a":1,"e":"Clovis, roi des Francs saliens, est baptisé à Reims par saint Remi : un geste qui lui assure le soutien de l'Église de Gaule."},{"id":3,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"En quelle année Charlemagne est-il couronné empereur à Rome ?","c":["732","800","843","987"],"a":1,"e":"Le pape Léon III couronne Charlemagne empereur le 25 décembre 800. 732 : bataille de Poitiers ; 843 : traité de Verdun ; 987 : avènement d'Hugues Capet."},{"id":4,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel maire du palais arrête une armée omeyyade près de Poitiers en 732 ?","c":["Carloman","Pépin le Bref","Charles Martel","Pépin de Herstal"],"a":2,"e":"Charles Martel, grand-père de Charlemagne, stoppe l'armée d'Abd al-Rahman entre Tours et Poitiers en 732."},{"id":5,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel traité partage en 843 l'empire carolingien entre trois petits-fils de Charlemagne ?","c":["Le traité de Verdun","Le traité de Meerssen","Le traité de Saint-Clair-sur-Epte","Le traité de Troyes"],"a":0,"e":"Verdun (843) partage l'empire entre Charles le Chauve, Louis le Germanique et Lothaire. Saint-Clair-sur-Epte (911) cède la Normandie à Rollon ; Troyes date de 1420."},{"id":6,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel événement de 987 marque le début de la dynastie capétienne ?","c":["Le sacre de Pépin le Bref à Saint-Denis","Le baptême de Clovis à Reims","La mort de Charles le Chauve","L'élection d'Hugues Capet comme roi des Francs"],"a":3,"e":"En 987, les grands du royaume élisent Hugues Capet ; ses descendants (Capétiens directs, Valois, Bourbons) régneront jusqu'en 1848."},{"id":7,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel duc de Normandie conquiert l'Angleterre après la bataille d'Hastings en 1066 ?","c":["Rollon","Guillaume le Conquérant","Richard Cœur de Lion","Robert Courteheuse"],"a":1,"e":"Guillaume, duc de Normandie, bat Harold à Hastings le 14 octobre 1066 et devient roi d'Angleterre."},{"id":8,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel pape lance l'appel à la première croisade au concile de Clermont en 1095 ?","c":["Grégoire VII","Urbain II","Innocent III","Boniface VIII"],"a":1,"e":"Urbain II prêche la croisade à Clermont en novembre 1095 ; Jérusalem est prise en 1099."},{"id":9,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi de France remporte la bataille de Bouvines en 1214 ?","c":["Louis VII","Louis IX (Saint Louis)","Louis VI le Gros","Philippe Auguste"],"a":3,"e":"Le 27 juillet 1214, Philippe II Auguste bat la coalition de l'empereur Otton IV, du comte de Flandre et du roi Jean sans Terre."},{"id":10,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Le roi Saint Louis rendait la justice sous un :","c":["bouleau","chêne","eucalyptus","flamboyant"],"a":1,"e":"La tradition, rapportée par le chroniqueur Joinville, montre Louis IX rendant la justice sous un chêne du bois de Vincennes.","o":"Annales 2023 · Q19"},{"id":11,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Où meurt Louis IX (Saint Louis) en 1270, lors de la huitième croisade ?","c":["À Saint-Jean-d'Acre","À Jérusalem","Devant Tunis","À Damiette"],"a":2,"e":"Saint Louis meurt, probablement de dysenterie, devant Tunis le 25 août 1270. Damiette avait été prise lors de la septième croisade (1249)."},{"id":12,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi fait arrêter les Templiers en 1307 ?","c":["Philippe IV le Bel","Philippe VI de Valois","Louis X le Hutin","Charles IV le Bel"],"a":0,"e":"Le 13 octobre 1307, Philippe le Bel fait arrêter les Templiers ; l'ordre est supprimé par le pape en 1312."},{"id":13,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Dans quelle ville les papes résident-ils de 1309 à 1377 ?","c":["Lyon","Avignon","Arles","Carpentras"],"a":1,"e":"La papauté s'installe à Avignon sous Clément V ; le palais des Papes y est construit au XIVe siècle."},{"id":14,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Entre quelles dates situe-t-on traditionnellement la guerre de Cent Ans ?","c":["1214-1314","1337-1453","1415-1515","1453-1559"],"a":1,"e":"La guerre de Cent Ans oppose les rois de France et d'Angleterre de 1337 à 1453 (victoire française de Castillon)."},{"id":15,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle ville Jeanne d'Arc délivre-t-elle du siège anglais en mai 1429 ?","c":["Rouen","Reims","Compiègne","Orléans"],"a":3,"e":"Jeanne d'Arc libère Orléans le 8 mai 1429 ; Charles VII est sacré à Reims en juillet. Elle est capturée à Compiègne (1430) et brûlée à Rouen (1431)."},{"id":16,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle bataille de 1415 voit la chevalerie française écrasée par les archers d'Henri V d'Angleterre ?","c":["Poitiers","Castillon","Azincourt","Crécy"],"a":2,"e":"Azincourt (25 octobre 1415). Crécy date de 1346, Poitiers de 1356 ; Castillon (1453) est au contraire une victoire française."},{"id":17,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi de France est fait prisonnier par les Anglais à la bataille de Poitiers en 1356 ?","c":["Charles VI","Philippe VI de Valois","Jean II le Bon","Charles V le Sage"],"a":2,"e":"Capturé par le Prince Noir, Jean le Bon est emmené à Londres ; sa rançon entraîne la création du franc en 1360."},{"id":18,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle épidémie ravage la France et l'Europe à partir de 1347-1348 ?","c":["Le choléra","Le typhus","La peste noire","La variole"],"a":2,"e":"La peste noire, arrivée par Marseille fin 1347, tue entre un tiers et la moitié de la population européenne."},{"id":19,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle abbaye bourguignonne, fondée en 910, devient le centre d'un vaste ordre monastique au Moyen Âge ?","c":["Cîteaux","Fontenay","Cluny","Vézelay"],"a":2,"e":"Fondée en 910 par Guillaume d'Aquitaine, Cluny dirige des centaines de prieurés. Cîteaux, berceau des cisterciens, date de 1098."},{"id":20,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel abbé fait reconstruire au XIIe siècle la basilique de Saint-Denis, souvent considérée comme le premier grand édifice gothique ?","c":["Suger","Alcuin","Bernard de Clairvaux","Pierre Abélard"],"a":0,"e":"Suger, abbé de Saint-Denis et conseiller de Louis VI et Louis VII, fait reconstruire la basilique entre 1135 et 1144."},{"id":21,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Contre quels chrétiens jugés hérétiques la croisade des albigeois est-elle lancée en 1209 ?","c":["Les cathares","Les huguenots","Les jansénistes","Les vaudois"],"a":0,"e":"La croisade des albigeois (1209-1229) vise les cathares du Languedoc. Les huguenots (protestants) et les jansénistes sont bien plus tardifs."},{"id":22,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle duchesse épouse successivement le roi de France Louis VII puis Henri II Plantagenêt ?","c":["Blanche de Castille","Isabeau de Bavière","Anne de Bretagne","Aliénor d'Aquitaine"],"a":3,"e":"Après l'annulation de son mariage avec Louis VII (1152), Aliénor épouse Henri Plantagenêt, futur roi d'Angleterre, apportant l'Aquitaine."},{"id":23,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Qui exerce la régence pendant la minorité de Louis IX (Saint Louis) ?","c":["Isabelle de France","Aliénor d'Aquitaine","Blanche de Castille","Marguerite de Provence"],"a":2,"e":"Blanche de Castille, mère de Louis IX, gouverne de 1226 à 1234 puis de nouveau pendant la croisade de son fils (1248-1252)."},{"id":24,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle bataille de 778, où périt le comte Roland, a inspiré « La Chanson de Roland » ?","c":["Fontenoy-en-Puisaye","Vouillé","Roncevaux","Tolbiac"],"a":2,"e":"En 778, l'arrière-garde de Charlemagne est massacrée au col de Roncevaux, dans les Pyrénées."},{"id":25,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Contre quel peuple Clovis remporte-t-il la bataille de Vouillé en 507 ?","c":["Les Alamans","Les Huns","Les Wisigoths","Les Burgondes"],"a":2,"e":"À Vouillé, Clovis bat le roi wisigoth Alaric II et s'empare de l'Aquitaine. Tolbiac l'avait opposé aux Alamans."},{"id":26,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Sous l'Empire romain, quel était le nom de la ville devenue Paris ?","c":["Lutèce","Massalia","Burdigala","Lugdunum"],"a":0,"e":"Lutèce (Lutetia), ville des Parisii. Lugdunum = Lyon, Burdigala = Bordeaux, Massalia = Marseille."},{"id":27,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quels Grecs fondent Massalia (Marseille) vers 600 av. J.-C. ?","c":["Les Corinthiens","Les Athéniens","Les Spartiates","Les Phocéens"],"a":3,"e":"Marseille est fondée vers 600 av. J.-C. par des marins de Phocée, cité grecque d'Asie Mineure ; on l'appelle encore la « cité phocéenne »."},{"id":28,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Dans quel département se trouve la grotte de Lascaux, célèbre pour ses peintures préhistoriques ?","c":["La Dordogne","Les Pyrénées-Atlantiques","L'Ardèche","L'Ariège"],"a":0,"e":"Lascaux (Montignac, Dordogne) est découverte en 1940. La grotte Chauvet se trouve en Ardèche, celle de Niaux en Ariège."},{"id":29,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi fait édifier à Paris, vers 1190, une enceinte et la forteresse du Louvre ?","c":["Charles V","Philippe le Bel","Louis IX","Philippe Auguste"],"a":3,"e":"Avant de partir en croisade (1190), Philippe Auguste fait entourer Paris d'une muraille et construire le château du Louvre."},{"id":30,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quelle broderie du XIe siècle raconte la conquête de l'Angleterre par Guillaume le Conquérant ?","c":["La tapisserie de Bayeux","La Dame à la licorne","La tenture de l'Apocalypse d'Angers","La tenture de l'Histoire du roi"],"a":0,"e":"La « tapisserie » de Bayeux, en réalité une broderie de près de 70 m, date des années 1070."},{"id":31,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel roi de France s'oppose au duc de Bourgogne Charles le Téméraire, mort devant Nancy en 1477 ?","c":["Louis XI","Charles VIII","Charles VII","Louis XII"],"a":0,"e":"Louis XI (1461-1483), surnommé « l'universelle aragne », profite de la mort du Téméraire pour récupérer la Bourgogne."},{"id":32,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Quel prévôt des marchands de Paris mène une révolte contre le dauphin Charles en 1358 ?","c":["Guillaume Cale","Hugues Aubriot","Étienne Marcel","Jacques Cœur"],"a":2,"e":"Étienne Marcel est tué en juillet 1358. Guillaume Cale dirigeait la Jacquerie ; Jacques Cœur fut l'argentier de Charles VII."},{"id":33,"m":"cg","t":"Histoire de France","s":"Antiquité et Moyen Âge","q":"Comment appelle-t-on le soulèvement paysan de 1358 en Île-de-France et en Picardie ?","c":["La Jacquerie","La révolte des Maillotins","La révolte des Croquants","La Fronde"],"a":0,"e":"La Jacquerie (mai-juin 1358) tire son nom de « Jacques Bonhomme », surnom donné aux paysans. Les Maillotins se soulèvent à Paris en 1382."},{"id":34,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quelle victoire de François Ier, en 1515, lui ouvre le Milanais ?","c":["Marignan","Fornoue","Pavie","Ravenne"],"a":0,"e":"Marignan (13-14 septembre 1515) contre les Suisses. Pavie (1525) est au contraire une défaite où le roi est capturé."},{"id":35,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Lors de quelle bataille François Ier est-il fait prisonnier par les troupes de Charles Quint en 1525 ?","c":["Saint-Quentin","Cérisoles","Pavie","Marignan"],"a":2,"e":"À Pavie (24 février 1525), François Ier est capturé et emmené à Madrid. Cérisoles (1544) est une victoire française."},{"id":36,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quelle ordonnance de 1539 impose l'usage du français dans les actes officiels et la justice ?","c":["L'ordonnance de Moulins","L'ordonnance de Villers-Cotterêts","L'édit de Fontainebleau","L'édit de Nantes"],"a":1,"e":"Signée par François Ier, l'ordonnance de Villers-Cotterêts impose le « langage maternel français » et crée les registres de baptêmes."},{"id":37,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Dans quelle demeure Léonard de Vinci, invité par François Ier, finit-il sa vie en 1519 ?","c":["Le château de Chambord","Le Clos Lucé, à Amboise","Le château de Fontainebleau","Le château de Blois"],"a":1,"e":"Léonard de Vinci s'installe en 1516 au manoir du Clos Lucé, près du château royal d'Amboise, où il meurt le 2 mai 1519."},{"id":38,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel roi fait construire le château de Chambord à partir de 1519 ?","c":["François Ier","Henri II","Charles VIII","Louis XII"],"a":0,"e":"Chambord, chef-d'œuvre de la Renaissance avec son escalier à double révolution, est lancé par François Ier en 1519."},{"id":39,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel navigateur explore le Saint-Laurent et prend possession du Canada au nom de François Ier en 1534 ?","c":["Jean de Verrazane","Samuel de Champlain","Jacques Cartier","Cavelier de La Salle"],"a":2,"e":"Le Malouin Jacques Cartier plante une croix à Gaspé en 1534. Champlain fonde Québec en 1608 ; Cavelier de La Salle descend le Mississippi en 1682."},{"id":40,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Qui fonde la ville de Québec en 1608 ?","c":["Samuel de Champlain","Pierre Le Moyne d'Iberville","Louis de Buade de Frontenac","Jacques Cartier"],"a":0,"e":"Samuel de Champlain fonde Québec le 3 juillet 1608, première implantation durable de la Nouvelle-France."},{"id":41,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"En quelle année a lieu le massacre de la Saint-Barthélemy ?","c":["1562","1572","1589","1598"],"a":1,"e":"Le 24 août 1572, des milliers de protestants sont massacrés à Paris puis en province. 1562 : massacre de Wassy ; 1589 : assassinat d'Henri III ; 1598 : édit de Nantes."},{"id":42,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel roi signe l'édit de Nantes en 1598 ?","c":["Henri III","Louis XIII","Charles IX","Henri IV"],"a":3,"e":"L'édit de Nantes (avril 1598) accorde aux protestants la liberté de culte et met fin aux guerres de Religion."},{"id":43,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Par qui Henri IV est-il assassiné en 1610 ?","c":["Jean Châtel","Jacques Clément","Robert-François Damiens","François Ravaillac"],"a":3,"e":"Ravaillac poignarde Henri IV rue de la Ferronnerie le 14 mai 1610. Jacques Clément a tué Henri III (1589) ; Damiens a frappé Louis XV (1757)."},{"id":44,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel ministre d'Henri IV est resté célèbre pour avoir assaini les finances du royaume ?","c":["Mazarin","Turgot","Colbert","Sully"],"a":3,"e":"Maximilien de Béthune, duc de Sully, surintendant des finances, rétablit l'équilibre budgétaire et développe l'agriculture (« Labourage et pâturage… »)."},{"id":45,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel cardinal est le principal ministre de Louis XIII de 1624 à 1642 ?","c":["Richelieu","Dubois","Fleury","Mazarin"],"a":0,"e":"Richelieu renforce l'autorité royale face aux grands et aux protestants (siège de La Rochelle, 1628). Mazarin lui succède auprès d'Anne d'Autriche."},{"id":46,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Qui fonde l'Académie française en 1635 ?","c":["Jean-Baptiste Colbert","Le cardinal Mazarin","Louis XIV","Le cardinal de Richelieu"],"a":3,"e":"Les lettres patentes de 1635 signées par Louis XIII officialisent l'Académie voulue par Richelieu pour fixer la langue française."},{"id":47,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Comment s'appelle la série de révoltes qui secoue le royaume entre 1648 et 1653, pendant la minorité de Louis XIV ?","c":["La Jacquerie","La Ligue","La guerre des Camisards","La Fronde"],"a":3,"e":"La Fronde (parlementaire puis des princes) s'oppose à Mazarin et à la régente Anne d'Autriche ; elle marque durablement le jeune Louis XIV."},{"id":48,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel ministre de Louis XIV développe les manufactures royales et la marine, au nom du mercantilisme ?","c":["Nicolas Fouquet","Louvois","Jean-Baptiste Colbert","Vauban"],"a":2,"e":"Contrôleur général des finances de 1665 à 1683, Colbert crée notamment les manufactures des Gobelins et de Saint-Gobain."},{"id":49,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel surintendant des finances, propriétaire de Vaux-le-Vicomte, est arrêté sur ordre de Louis XIV en 1661 ?","c":["Jean-Baptiste Colbert","Michel Le Tellier","Nicolas Fouquet","Le duc de Sully"],"a":2,"e":"Fouquet est arrêté à Nantes par d'Artagnan en septembre 1661, quelques semaines après une fête fastueuse à Vaux-le-Vicomte."},{"id":50,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Par quel texte Louis XIV révoque-t-il l'édit de Nantes en 1685 ?","c":["L'ordonnance de Blois","L'édit de Saint-Germain","L'édit de Versailles","L'édit de Fontainebleau"],"a":3,"e":"L'édit de Fontainebleau (octobre 1685) interdit le culte protestant : environ 200 000 huguenots quittent le royaume."},{"id":51,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"En quelle année Louis XIV installe-t-il officiellement la Cour et le gouvernement à Versailles ?","c":["1643","1661","1682","1715"],"a":2,"e":"La Cour s'installe à Versailles le 6 mai 1682. 1643 : avènement de Louis XIV ; 1661 : début du règne personnel ; 1715 : sa mort."},{"id":52,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel roi de France détient le plus long règne de l'histoire de France, soit 72 ans ?","c":["Philippe Auguste","Louis IX","Louis XV","Louis XIV"],"a":3,"e":"Louis XIV règne de 1643 à 1715. Louis XV règne 59 ans (1715-1774)."},{"id":53,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel ingénieur militaire de Louis XIV fortifie les frontières du royaume ?","c":["Jules Hardouin-Mansart","Vauban","André Le Nôtre","Turenne"],"a":1,"e":"Sébastien Le Prestre de Vauban construit ou remanie environ 300 places fortes ; douze sites sont inscrits au patrimoine mondial de l'Unesco."},{"id":54,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Qui dessine les jardins à la française du château de Versailles ?","c":["Jules Hardouin-Mansart","André Le Nôtre","Charles Le Brun","Louis Le Vau"],"a":1,"e":"Le Nôtre conçoit les jardins de Versailles (et de Vaux-le-Vicomte). Le Vau et Mansart sont architectes, Le Brun premier peintre du roi."},{"id":55,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel texte de 1685 réglemente l'esclavage dans les colonies françaises ?","c":["Le Code civil","L'Exclusif","Le Code noir","L'édit de Fontainebleau"],"a":2,"e":"Préparé sous Colbert et promulgué en 1685, le Code noir définit le statut des esclaves ; il est aboli avec l'esclavage en 1848."},{"id":56,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel roi de France est surnommé « le Bien-Aimé » ?","c":["Louis XIII","Louis XVI","Louis XIV","Louis XV"],"a":3,"e":"Louis XV reçoit ce surnom en 1744 lors de sa maladie à Metz. Louis XIV est le « Roi-Soleil », Louis XIII « le Juste »."},{"id":57,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Par quel traité de 1763, qui clôt la guerre de Sept Ans, la France cède-t-elle le Canada à la Grande-Bretagne ?","c":["Le traité d'Aix-la-Chapelle","Le traité de Paris","Le traité d'Utrecht","Le traité de Versailles"],"a":1,"e":"Le traité de Paris (10 février 1763) fait perdre à la France l'essentiel de son premier empire colonial. Le traité de Versailles de 1783 reconnaît l'indépendance américaine."},{"id":58,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel contrôleur général des finances de Louis XVI tente, de 1774 à 1776, de libéraliser le commerce des grains ?","c":["Loménie de Brienne","Calonne","Necker","Turgot"],"a":3,"e":"Turgot, physiocrate, veut supprimer la corvée et les corporations ; ses réformes suscitent l'opposition des privilégiés et il est renvoyé en 1776."},{"id":59,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel ministre d'origine genevoise publie en 1781 un « Compte rendu au roi » et voit son renvoi en juillet 1789 provoquer l'agitation parisienne ?","c":["Calonne","Malesherbes","Turgot","Jacques Necker"],"a":3,"e":"Le renvoi de Necker le 11 juillet 1789 contribue au soulèvement qui aboutit à la prise de la Bastille."},{"id":60,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quels philosophes dirigent la publication de l'« Encyclopédie » au XVIIIe siècle ?","c":["Buffon et Turgot","Voltaire et Rousseau","Montesquieu et Condorcet","Diderot et d'Alembert"],"a":3,"e":"L'Encyclopédie (1751-1772) est dirigée par Denis Diderot et Jean le Rond d'Alembert ; Voltaire, Rousseau ou Montesquieu y contribuent."},{"id":61,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel philosophe théorise la séparation des pouvoirs dans « De l'esprit des lois » (1748) ?","c":["Jean-Jacques Rousseau","Voltaire","Montesquieu","Denis Diderot"],"a":2,"e":"Montesquieu distingue pouvoirs législatif, exécutif et judiciaire : « il faut que, par la disposition des choses, le pouvoir arrête le pouvoir »."},{"id":62,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Qui est l'auteur de « Du contrat social » (1762) ?","c":["Montesquieu","Condorcet","Voltaire","Jean-Jacques Rousseau"],"a":3,"e":"Rousseau y fonde la souveraineté sur la « volonté générale » du peuple."},{"id":63,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Quel écrivain s'engage pour la réhabilitation de Jean Calas, protestant exécuté à Toulouse en 1762 ?","c":["Jean-Jacques Rousseau","Voltaire","Beaumarchais","Denis Diderot"],"a":1,"e":"Voltaire publie le « Traité sur la tolérance » (1763) ; Calas est réhabilité en 1765."},{"id":64,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Sous l'Ancien Régime, sur quel produit porte l'impôt appelé « gabelle » ?","c":["Le sel","Le tabac","Le blé","Le vin"],"a":0,"e":"La gabelle est l'impôt sur le sel, très impopulaire ; ses taux variaient fortement selon les provinces."},{"id":65,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Sous l'Ancien Régime, quel impôt direct pèse principalement sur les roturiers, la noblesse et le clergé en étant exemptés ?","c":["La dîme","La gabelle","La taille","Les aides"],"a":2,"e":"La taille est l'impôt direct royal. La dîme est versée à l'Église ; la gabelle et les aides sont des impôts indirects."},{"id":66,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Comment appelle-t-on les financiers qui, sous l'Ancien Régime, perçoivent certains impôts indirects pour le compte du roi ?","c":["Les intendants","Les fermiers généraux","Les parlementaires","Les baillis"],"a":1,"e":"La Ferme générale avance au roi le produit attendu des impôts indirects (gabelle, aides, traites) puis les collecte. Le chimiste Lavoisier fut fermier général."},{"id":67,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"Sous Louis XIII et Louis XIV, quels agents du roi représentent son autorité dans les généralités ?","c":["Les intendants","Les préfets","Les fermiers généraux","Les sénéchaux"],"a":0,"e":"Les intendants « de justice, police et finances » sont les ancêtres des préfets, créés eux en 1800."},{"id":68,"m":"cg","t":"Histoire de France","s":"Renaissance et Ancien Régime","q":"De quel pays Marie-Antoinette, épouse de Louis XVI, est-elle originaire ?","c":["La Bavière","L'Espagne","La Savoie","L'Autriche"],"a":3,"e":"Fille de l'impératrice Marie-Thérèse, Marie-Antoinette épouse le futur Louis XVI en 1770."},{"id":69,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quand s'ouvrent les états généraux à Versailles ?","c":["5 mai 1789","20 juin 1789","14 juillet 1789","4 août 1789"],"a":0,"e":"Les états généraux s'ouvrent le 5 mai 1789. 20 juin : serment du Jeu de paume ; 14 juillet : prise de la Bastille ; 4 août : abolition des privilèges."},{"id":70,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Que s'engagent à faire les députés lors du serment du Jeu de paume (20 juin 1789) ?","c":["Rétablir le vote par ordre aux états généraux","Abolir les privilèges et les droits féodaux","Rédiger les cahiers de doléances","Ne pas se séparer avant d'avoir donné une constitution au royaume"],"a":3,"e":"Réunis dans la salle du Jeu de paume, les députés du tiers état jurent de ne pas se séparer avant d'avoir rédigé une constitution."},{"id":71,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel événement du 14 juillet 1789 devient le symbole de la Révolution ?","c":["Le serment du Jeu de paume","La marche des femmes sur Versailles","La fête de la Fédération","La prise de la Bastille"],"a":3,"e":"La Bastille, prison royale, est prise le 14 juillet 1789. La fête de la Fédération a lieu le 14 juillet 1790 ; la marche sur Versailles en octobre 1789."},{"id":72,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Que décide l'Assemblée nationale constituante lors de la nuit du 4 août 1789 ?","c":["La suppression de la monarchie","La création des départements","L'abolition des privilèges","L'adoption de la Déclaration des droits de l'homme"],"a":2,"e":"La nuit du 4 août met fin aux privilèges et au régime féodal. La Déclaration date du 26 août, la République du 21 septembre 1792."},{"id":73,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle date porte la Déclaration des droits de l'homme et du citoyen ?","c":["4 août 1789","26 août 1789","3 septembre 1791","24 juin 1793"],"a":1,"e":"Adoptée le 26 août 1789, la DDHC figure aujourd'hui dans le bloc de constitutionnalité."},{"id":74,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"En quelle année les départements sont-ils mis en place en France ?","c":["1790","1800","1815","1871"],"a":0,"e":"Décidés par la Constituante fin 1789, les 83 premiers départements sont officiellement créés le 4 mars 1790."},{"id":75,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Où Louis XVI et sa famille sont-ils arrêtés lors de leur fuite en juin 1791 ?","c":["À Varennes","À Sainte-Menehould","À Montmédy","À Metz"],"a":0,"e":"Reconnu à Sainte-Menehould par le maître de poste Drouet, le roi est arrêté à Varennes le 21 juin 1791 ; il voulait rejoindre Montmédy."},{"id":76,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle bataille du 20 septembre 1792, remportée contre les Prussiens, précède de peu la proclamation de la République ?","c":["Jemmapes","Fleurus","Valmy","Wattignies"],"a":2,"e":"La canonnade de Valmy arrête l'invasion prussienne ; la royauté est abolie le lendemain, le 21 septembre 1792."},{"id":77,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"En quelle année la Première République est-elle proclamée ?","c":["1789","1791","1792","1793"],"a":2,"e":"La Convention abolit la royauté le 21 septembre 1792 ; l'an I de la République commence le 22 septembre 1792."},{"id":78,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"À quelle date Louis XVI est-il guillotiné ?","c":["10 août 1792","21 janvier 1793","16 octobre 1793","28 juillet 1794"],"a":1,"e":"Louis XVI est exécuté place de la Révolution (actuelle Concorde). 10 août 1792 : prise des Tuileries ; 16 octobre 1793 : exécution de Marie-Antoinette ; 28 juillet 1794 : exécution de Robespierre."},{"id":79,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel député montagnard, figure du Comité de salut public, est renversé le 9 Thermidor an II (27 juillet 1794) ?","c":["Georges Danton","Maximilien de Robespierre","Jean-Paul Marat","Jacques-René Hébert"],"a":1,"e":"Robespierre est arrêté le 9 Thermidor et guillotiné le lendemain. Danton et Hébert avaient été exécutés au printemps 1794 ; Marat assassiné en 1793."},{"id":80,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Qui assassine Jean-Paul Marat dans sa baignoire en juillet 1793 ?","c":["Charlotte Corday","Madame Roland","Théroigne de Méricourt","Olympe de Gouges"],"a":0,"e":"Charlotte Corday, proche des Girondins, poignarde Marat le 13 juillet 1793 ; la scène est immortalisée par le peintre David."},{"id":81,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Qui rédige en 1791 la « Déclaration des droits de la femme et de la citoyenne » ?","c":["Germaine de Staël","Louise Michel","Madame Roland","Olympe de Gouges"],"a":3,"e":"Olympe de Gouges réclame l'égalité civique des femmes ; elle est guillotinée en 1793."},{"id":82,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Qui compose « La Marseillaise » en 1792 ?","c":["André Chénier","Étienne Méhul","Claude Joseph Rouget de Lisle","François-Joseph Gossec"],"a":2,"e":"Écrit à Strasbourg en avril 1792 sous le titre « Chant de guerre pour l'armée du Rhin », l'hymne est popularisé par les fédérés marseillais."},{"id":83,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Le mètre, adopté sous la Révolution, est d'abord défini comme :","c":["la quarante-millionième partie de l'équateur","la longueur d'un pendule qui bat la seconde","la distance parcourue par la lumière en une seconde","la dix-millionième partie du quart du méridien terrestre"],"a":3,"e":"Le mètre de 1791-1799 repose sur la mesure du méridien de Dunkerque à Barcelone par Delambre et Méchain."},{"id":84,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel mois du calendrier républicain tombe en plein été ?","c":["Germinal","Brumaire","Floréal","Thermidor"],"a":3,"e":"Thermidor couvre environ la période du 19 juillet au 17 août. Brumaire est un mois d'automne, Germinal et Floréal des mois de printemps."},{"id":85,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Par quel coup d'État Napoléon Bonaparte prend-il le pouvoir en novembre 1799 ?","c":["Le 18 Brumaire","Le 9 Thermidor","Le 13 Vendémiaire","Le 18 Fructidor"],"a":0,"e":"Le 18 Brumaire an VIII (9 novembre 1799) renverse le Directoire et instaure le Consulat."},{"id":86,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"En quelle année le Code civil (Code Napoléon) est-il promulgué ?","c":["1799","1802","1804","1810"],"a":2,"e":"Le Code civil des Français est promulgué le 21 mars 1804. Le Code pénal date de 1810."},{"id":87,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Où Napoléon Ier est-il sacré empereur le 2 décembre 1804 ?","c":["À la basilique de Saint-Denis","Au palais des Tuileries","À Notre-Dame de Paris","À la cathédrale de Reims"],"a":2,"e":"Le sacre a lieu à Notre-Dame en présence du pape Pie VII ; Napoléon se couronne lui-même."},{"id":88,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle victoire de Napoléon, le 2 décembre 1805, est appelée « bataille des Trois Empereurs » ?","c":["Austerlitz","Friedland","Iéna","Wagram"],"a":0,"e":"À Austerlitz, Napoléon bat les empereurs d'Autriche (François II) et de Russie (Alexandre Ier)."},{"id":89,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle bataille navale de 1805 voit la flotte franco-espagnole battue par l'amiral Nelson ?","c":["Trafalgar","Lépante","Aboukir","Navarin"],"a":0,"e":"Trafalgar (21 octobre 1805) assure aux Britanniques la maîtrise des mers ; Nelson y est tué."},{"id":90,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle distinction Napoléon Bonaparte crée-t-il en 1802 ?","c":["L'ordre national du Mérite","La croix de guerre","La Légion d'honneur","La Médaille militaire"],"a":2,"e":"La Légion d'honneur est créée le 19 mai 1802. L'ordre national du Mérite date de 1963, la Médaille militaire de 1852, la croix de guerre de 1915."},{"id":91,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Avec quel pape Bonaparte signe-t-il le Concordat de 1801 ?","c":["Léon XII","Pie VI","Grégoire XVI","Pie VII"],"a":3,"e":"Le Concordat de 1801 régit les relations entre l'État et l'Église catholique jusqu'en 1905 (il s'applique toujours en Alsace-Moselle)."},{"id":92,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle institution Bonaparte crée-t-il en 1800 pour émettre la monnaie et soutenir le crédit ?","c":["Le Crédit lyonnais","La Banque de France","La Bourse de Paris","La Caisse des dépôts et consignations"],"a":1,"e":"La Banque de France est fondée le 18 janvier 1800. La Caisse des dépôts date de 1816, le Crédit lyonnais de 1863."},{"id":93,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quels établissements d'enseignement Napoléon Bonaparte crée-t-il par la loi de 1802 ?","c":["Les écoles normales d'instituteurs","Les universités populaires","L'École polytechnique","Les lycées"],"a":3,"e":"La loi du 1er mai 1802 crée les lycées. L'École polytechnique date de 1794."},{"id":94,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel passage de rivière, en novembre 1812, marque la retraite de Russie de la Grande Armée ?","c":["La Bérézina","Le Dniepr","La Moskova","Le Niémen"],"a":0,"e":"La traversée de la Bérézina (26-29 novembre 1812) est devenue synonyme de désastre. La Grande Armée avait franchi le Niémen en juin."},{"id":95,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Sur quelle île Napoléon est-il exilé après sa première abdication en 1814 ?","c":["La Corse","L'île d'Aix","L'île d'Elbe","Sainte-Hélène"],"a":2,"e":"Exilé à l'île d'Elbe, Napoléon s'en échappe en mars 1815 pour les Cent-Jours. Après Waterloo, il est déporté à Sainte-Hélène."},{"id":96,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Où est mort Napoléon ?","c":["Ajaccio","Bastia","Île d'Elbe","Île de Sainte-Hélène"],"a":3,"e":"Napoléon meurt le 5 mai 1821 à Sainte-Hélène, île britannique de l'Atlantique Sud. Il était né à Ajaccio en 1769.","o":"Annales 2022 · Q17"},{"id":97,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"À quelle date a lieu la bataille de Waterloo ?","c":["2 décembre 1805","14 octobre 1806","18 juin 1815","5 mai 1821"],"a":2,"e":"Waterloo (18 juin 1815) met fin aux Cent-Jours. 2 décembre 1805 : Austerlitz ; 14 octobre 1806 : Iéna ; 5 mai 1821 : mort de Napoléon."},{"id":98,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quelle expédition de Bonaparte (1798-1801) permet la découverte de la pierre de Rosette ?","c":["L'expédition de Saint-Domingue","L'expédition d'Égypte","La campagne d'Italie","La campagne d'Espagne"],"a":1,"e":"Découverte en 1799, la pierre de Rosette permet à Champollion de déchiffrer les hiéroglyphes en 1822."},{"id":99,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel est l'objectif du Blocus continental décrété par Napoléon en 1806 ?","c":["Fermer les ports espagnols aux navires américains","Empêcher la Russie d'accéder à la mer Baltique","Interdire l'importation de céréales en France","Ruiner le commerce britannique en fermant l'Europe à ses marchandises"],"a":3,"e":"Le décret de Berlin (novembre 1806) interdit tout commerce avec le Royaume-Uni."},{"id":100,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel chef de la révolution de Saint-Domingue meurt en captivité au fort de Joux, dans le Jura, en 1803 ?","c":["Jean-Jacques Dessalines","Alexandre Pétion","Toussaint Louverture","Henri Christophe"],"a":2,"e":"Arrêté sur ordre de Bonaparte, Toussaint Louverture meurt au fort de Joux. Dessalines proclame l'indépendance d'Haïti en 1804."},{"id":101,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"En quelle année Bonaparte rétablit-il l'esclavage dans les colonies, alors qu'il avait été aboli en 1794 ?","c":["1799","1802","1804","1815"],"a":1,"e":"La loi du 20 mai 1802 maintient puis rétablit l'esclavage. Il ne sera définitivement aboli qu'en 1848."},{"id":102,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Comment appelle-t-on l'insurrection royaliste et catholique qui éclate dans l'Ouest de la France en mars 1793 ?","c":["La guerre de Vendée","La Terreur blanche","La Grande Peur","La conjuration des Égaux"],"a":0,"e":"Déclenchée par la levée de 300 000 hommes, la guerre de Vendée fait des dizaines de milliers de morts. La Grande Peur date de l'été 1789."},{"id":103,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel régime instaure la Constitution de 1791 ?","c":["Une république présidentielle","Un consulat","Une monarchie absolue de droit divin","Une monarchie constitutionnelle"],"a":3,"e":"La Constitution du 3 septembre 1791 limite le pouvoir du roi, qui partage l'autorité avec l'Assemblée législative."},{"id":104,"m":"cg","t":"Histoire de France","s":"Révolution et Empire","q":"Quel régime gouverne la France entre 1795 et 1799 ?","c":["La Convention","Le Directoire","La Restauration","Le Consulat"],"a":1,"e":"Le Directoire, avec cinq directeurs et deux conseils, succède à la Convention en 1795 et tombe le 18 Brumaire."},{"id":105,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel roi monte sur le trône lors de la Restauration, en 1814 ?","c":["Louis XVIII","Louis-Philippe Ier","Louis XVII","Charles X"],"a":0,"e":"Frère de Louis XVI, Louis XVIII règne de 1814 à 1824 (avec l'interruption des Cent-Jours). Louis XVII, mort en 1795, n'a jamais régné."},{"id":106,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quelle révolution de juillet 1830 renverse Charles X ?","c":["La Commune","La révolution de Février","Les journées de Juin","Les Trois Glorieuses"],"a":3,"e":"Les 27, 28 et 29 juillet 1830, Paris se soulève contre les ordonnances de Charles X ; Louis-Philippe devient « roi des Français »."},{"id":107,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel souverain, qui règne de 1830 à 1848, porte le titre de « roi des Français » ?","c":["Charles X","Napoléon III","Louis XVIII","Louis-Philippe Ier"],"a":3,"e":"La monarchie de Juillet de Louis-Philippe tombe lors de la révolution de février 1848."},{"id":108,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel homme politique est à l'origine du décret d'abolition de l'esclavage du 27 avril 1848 ?","c":["Alphonse de Lamartine","Louis Blanc","Victor Schœlcher","Alexandre Ledru-Rollin"],"a":2,"e":"Sous-secrétaire d'État aux colonies, Victor Schœlcher fait adopter l'abolition définitive de l'esclavage ; il repose au Panthéon."},{"id":109,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"En quelle année le suffrage universel masculin est-il instauré durablement en France ?","c":["1792","1830","1848","1875"],"a":2,"e":"Le décret du 5 mars 1848 instaure le suffrage universel masculin ; il ne sera plus remis en cause durablement."},{"id":110,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Qui est le premier président de la République élu au suffrage universel, en décembre 1848 ?","c":["Adolphe Thiers","Patrice de Mac Mahon","Alphonse de Lamartine","Louis-Napoléon Bonaparte"],"a":3,"e":"Louis-Napoléon Bonaparte, neveu de Napoléon Ier, est élu avec près de 75 % des voix le 10 décembre 1848."},{"id":111,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel événement du 2 décembre 1851 met fin à la IIe République ?","c":["Le coup d'État de Louis-Napoléon Bonaparte","La révolution de Février","L'insurrection de la Commune","La défaite de Sedan"],"a":0,"e":"Le prince-président dissout l'Assemblée ; un an plus tard, le 2 décembre 1852, il devient l'empereur Napoléon III."},{"id":112,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel préfet de la Seine transforme Paris sous le Second Empire ?","c":["Gustave Eiffel","Jean-Charles Alphand","Le baron Haussmann","Eugène Belgrand"],"a":2,"e":"Préfet de 1853 à 1870, Haussmann perce les grands boulevards. Alphand (parcs) et Belgrand (égouts, eau) travaillent sous ses ordres."},{"id":113,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Lors de quelle bataille Napoléon III est-il fait prisonnier par les Prussiens en septembre 1870 ?","c":["Gravelotte","Reichshoffen","Sedan","Metz"],"a":2,"e":"La capitulation de Sedan (2 septembre 1870) entraîne la chute du Second Empire deux jours plus tard."},{"id":114,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel jour la IIIe République est-elle proclamée ?","c":["2 décembre 1851","4 septembre 1870","18 mars 1871","30 janvier 1875"],"a":1,"e":"La République est proclamée à l'hôtel de ville de Paris le 4 septembre 1870. 18 mars 1871 : début de la Commune ; 30 janvier 1875 : amendement Wallon."},{"id":115,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Comment appelle-t-on la répression de la Commune de Paris par les troupes versaillaises, fin mai 1871 ?","c":["La Grande Peur","La Terreur blanche","Les journées de Juin","La Semaine sanglante"],"a":3,"e":"Du 21 au 28 mai 1871, la Semaine sanglante fait plusieurs milliers de morts parmi les communards."},{"id":116,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quelle institutrice, figure de la Commune de Paris, est déportée en Nouvelle-Calédonie ?","c":["Flora Tristan","George Sand","Louise Michel","Hubertine Auclert"],"a":2,"e":"Surnommée la « Vierge rouge », Louise Michel est déportée de 1873 à 1880."},{"id":117,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Par quel traité la France cède-t-elle l'Alsace et une partie de la Lorraine à l'Empire allemand en 1871 ?","c":["Le traité de Berlin","Le traité de Francfort","Le traité de Vienne","Le traité de Versailles"],"a":1,"e":"Le traité de Francfort (10 mai 1871) impose aussi une indemnité de 5 milliards de francs-or. Les territoires sont récupérés en 1918-1919."},{"id":118,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Que rendent les lois Jules Ferry de 1881-1882 ?","c":["Le divorce légal","Le repos hebdomadaire obligatoire","L'école primaire gratuite, obligatoire et laïque","Le service militaire obligatoire pour tous"],"a":2,"e":"Lois du 16 juin 1881 (gratuité) et du 28 mars 1882 (obligation et laïcité). Le divorce est rétabli par la loi Naquet de 1884."},{"id":119,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quelle loi de 1884 autorise la création des syndicats professionnels ?","c":["La loi Waldeck-Rousseau","La loi Naquet","La loi Falloux","La loi Le Chapelier"],"a":0,"e":"La loi du 21 mars 1884 abroge la loi Le Chapelier de 1791 qui interdisait les groupements professionnels. La loi Falloux (1850) concerne l'enseignement."},{"id":120,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Dans quel journal Émile Zola publie-t-il « J'accuse… ! » en 1898 ?","c":["Le Figaro","Le Petit Journal","L'Humanité","L'Aurore"],"a":3,"e":"La lettre ouverte au président Félix Faure paraît le 13 janvier 1898 dans L'Aurore de Clemenceau. L'Humanité n'est fondée qu'en 1904."},{"id":121,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel officier, accusé à tort de trahison en 1894, est au cœur d'une affaire qui divise la France ?","c":["Le général Boulanger","Le capitaine Alfred Dreyfus","Le commandant Esterhazy","Le colonel Picquart"],"a":1,"e":"Dreyfus est réhabilité en 1906. Le vrai coupable était Esterhazy ; Picquart l'avait découvert."},{"id":122,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"En quelle année est votée la loi de séparation des Églises et de l'État ?","c":["1882","1901","1905","1946"],"a":2,"e":"Loi du 9 décembre 1905 : la République assure la liberté de conscience et ne reconnaît ni ne subventionne aucun culte."},{"id":123,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Que permet principalement la loi du 1er juillet 1901 ?","c":["La liberté de la presse","La séparation des Églises et de l'État","Le droit de grève","La liberté de créer des associations"],"a":3,"e":"La loi Waldeck-Rousseau de 1901 fonde le régime des associations. La liberté de la presse date de 1881, le droit de grève de 1864."},{"id":124,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"En quelle année est adoptée la grande loi sur la liberté de la presse ?","c":["1848","1864","1881","1905"],"a":2,"e":"La loi du 29 juillet 1881 est toujours en vigueur ; elle encadre aussi la diffamation et l'affichage."},{"id":125,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quelle loi de 1864 supprime le délit de coalition et reconnaît ainsi le droit de grève ?","c":["La loi Ollivier","La loi Guizot","La loi Waldeck-Rousseau","La loi Le Chapelier"],"a":0,"e":"Portée par Émile Ollivier sous Napoléon III, la loi du 25 mai 1864 dépénalise la grève. La loi Guizot (1833) concerne les écoles primaires."},{"id":126,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Depuis quelle année le 14 Juillet est-il la fête nationale ?","c":["1790","1830","1880","1945"],"a":2,"e":"La loi du 6 juillet 1880 fait du 14 Juillet la fête nationale, en souvenir de 1789 et de la fête de la Fédération de 1790."},{"id":127,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"En quelle année débute la conquête de l'Algérie par la France, avec la prise d'Alger ?","c":["1798","1830","1848","1881"],"a":1,"e":"Alger est prise le 5 juillet 1830, sous Charles X. 1881 est l'année du protectorat sur la Tunisie."},{"id":128,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel émir mène la résistance à la conquête française de l'Algérie jusqu'à sa reddition en 1847 ?","c":["Abdelkrim el-Khattabi","Abd el-Kader","Messali Hadj","Ferhat Abbas"],"a":1,"e":"L'émir Abd el-Kader combat de 1832 à 1847. Abdelkrim mène la guerre du Rif dans les années 1920 ; Messali Hadj et Ferhat Abbas sont des nationalistes du XXe siècle."},{"id":129,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"À l'occasion de quel événement la tour Eiffel est-elle construite ?","c":["L'Exposition universelle de 1889","Les Jeux olympiques de 1900","L'Exposition coloniale de 1931","L'Exposition universelle de 1900"],"a":0,"e":"Inaugurée en 1889 pour le centenaire de la Révolution, la tour devait être démontée au bout de vingt ans."},{"id":130,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel général, ministre de la Guerre, incarne à la fin des années 1880 un mouvement populiste menaçant la République ?","c":["Patrice de Mac Mahon","Louis Faidherbe","Georges Boulanger","Hubert Lyautey"],"a":2,"e":"Le boulangisme culmine en janvier 1889 ; le général s'enfuit ensuite en Belgique, où il se suicide en 1891."},{"id":131,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel président de la République démissionne en 1879, après la crise du 16 mai 1877 qui l'a opposé à la Chambre des députés ?","c":["Patrice de Mac Mahon","Adolphe Thiers","Jules Grévy","Sadi Carnot"],"a":0,"e":"La crise du 16 mai 1877 consacre la primauté de la Chambre ; Mac Mahon démissionne en janvier 1879 et Jules Grévy lui succède."},{"id":132,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel président de la République est assassiné à Lyon en 1894 par un anarchiste ?","c":["Félix Faure","Paul Doumer","Jean Casimir-Perier","Sadi Carnot"],"a":3,"e":"Sadi Carnot est poignardé par Caserio le 24 juin 1894. Paul Doumer sera assassiné à Paris en 1932."},{"id":133,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Qui sont les « canuts », révoltés à Lyon en 1831 et 1834 ?","c":["Les ouvriers de la soie","Les vignerons du Beaujolais","Les dockers du port fluvial","Les mineurs de charbon"],"a":0,"e":"Les canuts, tisserands de la soie de la Croix-Rousse, se soulèvent pour un tarif minimum : « Vivre en travaillant ou mourir en combattant »."},{"id":134,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quelle est la première ligne de chemin de fer pour voyageurs au départ de Paris, inaugurée en 1837 ?","c":["Paris – Orléans","Paris – Versailles","Paris – Rouen","Paris – Saint-Germain-en-Laye"],"a":3,"e":"La ligne de Paris au Pecq, au pied de Saint-Germain-en-Laye, est inaugurée le 24 août 1837."},{"id":135,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Dans quel pays le Second Empire mène-t-il une expédition militaire pour imposer l'empereur Maximilien, entre 1861 et 1867 ?","c":["Le Pérou","L'Égypte","Le Mexique","Le Brésil"],"a":2,"e":"L'expédition du Mexique se solde par un échec ; Maximilien est fusillé en 1867."},{"id":136,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Qui dirige le gouvernement qui écrase la Commune de Paris en 1871 ?","c":["Adolphe Thiers","Jules Ferry","Léon Gambetta","Jules Favre"],"a":0,"e":"Chef du pouvoir exécutif installé à Versailles, Thiers ordonne la reconquête de Paris ; il devient président de la République en août 1871."},{"id":137,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel républicain quitte Paris assiégé en ballon en octobre 1870 pour organiser la résistance en province ?","c":["Adolphe Thiers","Jules Ferry","Léon Gambetta","Victor Hugo"],"a":2,"e":"Le 7 octobre 1870, Gambetta s'envole de Montmartre en ballon et rejoint Tours, où il lève de nouvelles armées."},{"id":138,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Quel amendement de 1875, adopté à une voix de majorité, installe définitivement la République dans les lois constitutionnelles ?","c":["L'amendement Buffet","L'amendement Wallon","L'amendement de Broglie","L'amendement Grévy"],"a":1,"e":"L'amendement d'Henri Wallon (30 janvier 1875) précise que le président de la République est élu par les deux chambres : 353 voix contre 352."},{"id":139,"m":"cg","t":"Histoire de France","s":"XIXe siècle","q":"Où se trouve Hauteville House, la maison d'exil de Victor Hugo sous le Second Empire ?","c":["À Guernesey","À Bruxelles","À Jersey","À Londres"],"a":0,"e":"Opposant à Napoléon III, Victor Hugo vit en exil à Jersey puis, de 1855 à 1870, à Guernesey, où il écrit notamment « Les Misérables »."},{"id":140,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel événement du 28 juin 1914 déclenche la crise menant à la Première Guerre mondiale ?","c":["Le naufrage du paquebot Lusitania","L'invasion de la Belgique par l'Allemagne","L'assassinat de Jean Jaurès à Paris","L'assassinat de l'archiduc François-Ferdinand à Sarajevo"],"a":3,"e":"L'héritier de l'Autriche-Hongrie est tué par le nationaliste serbe Gavrilo Princip ; l'enchaînement des alliances mène à la guerre en août."},{"id":141,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel dirigeant socialiste pacifiste est assassiné à Paris le 31 juillet 1914 ?","c":["Léon Blum","Jean Jaurès","Jules Guesde","Aristide Briand"],"a":1,"e":"Fondateur de L'Humanité, Jaurès est abattu au café du Croissant par Raoul Villain, trois jours avant l'entrée en guerre de la France."},{"id":142,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle expression, employée par le président Poincaré en août 1914, désigne le rassemblement des Français de toutes tendances face à la guerre ?","c":["Le Bloc national","L'Union sacrée","Le Cartel des gauches","Le Front populaire"],"a":1,"e":"Dans son message du 4 août 1914, Raymond Poincaré appelle à l'« union sacrée ». Le Bloc national (1919) et le Cartel des gauches (1924) sont des coalitions électorales."},{"id":143,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle bataille de septembre 1914 stoppe l'avancée allemande vers Paris, avec l'épisode des « taxis » ?","c":["La bataille de Verdun","La première bataille de la Marne","La bataille de Charleroi","La bataille de la Somme"],"a":1,"e":"Du 5 au 12 septembre 1914, Joffre et Gallieni arrêtent les Allemands ; des taxis parisiens acheminent des renforts."},{"id":144,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"En quelle année se déroule la bataille de Verdun ?","c":["1914","1915","1916","1918"],"a":2,"e":"De février à décembre 1916, Verdun fait environ 300 000 morts français et allemands."},{"id":145,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel général commande l'offensive du Chemin des Dames en avril 1917, dont l'échec entraîne des mutineries ?","c":["Robert Nivelle","Ferdinand Foch","Philippe Pétain","Joseph Joffre"],"a":0,"e":"Après l'échec de l'offensive Nivelle, Pétain le remplace en mai 1917 et met fin aux mutineries en améliorant le sort des soldats."},{"id":146,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Où est signé l'armistice du 11 novembre 1918 ?","c":["À Reims, au quartier général allié","Dans la clairière de Rethondes, en forêt de Compiègne","À Spa, en Belgique","Dans la galerie des Glaces du château de Versailles"],"a":1,"e":"L'armistice est signé dans le wagon du maréchal Foch. Le traité de paix est signé dans la galerie des Glaces le 28 juin 1919."},{"id":147,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel traité a mis fin à la Première Guerre mondiale ?","c":["Le traité de Berlin","Le traité de Londres","Le traité de Paris","Le traité de Versailles"],"a":3,"e":"Signé le 28 juin 1919, le traité de Versailles impose à l'Allemagne la restitution de l'Alsace-Moselle et de lourdes réparations.","o":"Sujet zéro 2026 · Q1"},{"id":148,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel président du Conseil est surnommé « le Père la Victoire » ?","c":["Paul Painlevé","Raymond Poincaré","Aristide Briand","Georges Clemenceau"],"a":3,"e":"Clemenceau, président du Conseil de novembre 1917 à 1920, galvanise le pays jusqu'à la victoire. Poincaré était président de la République."},{"id":149,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Qui est nommé en 1918 commandant en chef des armées alliées sur le front occidental ?","c":["Joseph Joffre","Philippe Pétain","Ferdinand Foch","Douglas Haig"],"a":2,"e":"Foch reçoit le commandement unique en mars-avril 1918 et devient maréchal en août 1918."},{"id":150,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel surnom donne-t-on aux soldats français de la Première Guerre mondiale ?","c":["Les poilus","Les grognards","Les maquisards","Les marie-louise"],"a":0,"e":"« Poilu » désigne le soldat courageux. Les grognards sont les vétérans de la Garde de Napoléon ; les maquisards, des résistants de 1943-1944."},{"id":151,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Combien de militaires français environ sont morts pendant la Première Guerre mondiale ?","c":["300 000","600 000","1,4 million","4 millions"],"a":2,"e":"Environ 1,4 million de soldats français sont tués ; près de 18 millions de personnes meurent dans le monde."},{"id":152,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel président du Conseil dirige le gouvernement du Front populaire, qui instaure les congés payés en 1936 ?","c":["Pierre Laval","Édouard Daladier","Édouard Herriot","Léon Blum"],"a":3,"e":"Le gouvernement de Léon Blum fait voter deux semaines de congés payés et la semaine de 40 heures après les accords de Matignon (juin 1936)."},{"id":153,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle durée hebdomadaire du travail est fixée par la loi de juin 1936 ?","c":["35 heures","39 heures","40 heures","48 heures"],"a":2,"e":"La loi du 21 juin 1936 fixe la semaine à 40 heures. Les 39 heures datent de 1982, les 35 heures de 1998-2000."},{"id":154,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel président du Conseil français signe les accords de Munich en septembre 1938 ?","c":["Albert Lebrun","Édouard Daladier","Léon Blum","Paul Reynaud"],"a":1,"e":"Daladier et Chamberlain acceptent l'annexion des Sudètes par Hitler. Albert Lebrun était alors président de la République."},{"id":155,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"À quelle date la France déclare-t-elle la guerre à l'Allemagne ?","c":["1er septembre 1939","3 septembre 1939","10 mai 1940","22 juin 1940"],"a":1,"e":"La France et le Royaume-Uni déclarent la guerre le 3 septembre 1939, deux jours après l'invasion de la Pologne. L'offensive allemande débute le 10 mai 1940 ; l'armistice est signé le 22 juin 1940."},{"id":156,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Comment s'appelle la ligne de fortifications construite par la France face à l'Allemagne dans les années 1930 ?","c":["La ligne Weygand","La ligne Maginot","Le mur de l'Atlantique","La ligne Siegfried"],"a":1,"e":"Du nom du ministre André Maginot, elle est contournée par les Allemands via les Ardennes en mai 1940. La ligne Siegfried était allemande."},{"id":157,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Depuis quelle ville le général de Gaulle lance-t-il son appel du 18 juin 1940 ?","c":["Alger","Bordeaux","Brazzaville","Londres"],"a":3,"e":"De Gaulle parle au micro de la BBC à Londres. Le gouvernement français s'était replié à Bordeaux ; le manifeste de Brazzaville date d'octobre 1940."},{"id":158,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Qui était le chef de file de la Résistance française pendant la Seconde Guerre mondiale ?","c":["Léon Blum","Charles de Gaulle","Pierre Laval","Philippe Pétain"],"a":1,"e":"Le général de Gaulle dirige la France libre depuis Londres puis Alger. Pétain et Laval incarnent au contraire la collaboration.","o":"Sujet zéro 2026 · Q6"},{"id":159,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Le 10 juillet 1940, à qui le Parlement réuni à Vichy vote-t-il les pleins pouvoirs ?","c":["Au général Weygand","Au maréchal Pétain","À l'amiral Darlan","À Pierre Laval"],"a":1,"e":"Par 569 voix contre 80, les parlementaires confient les pleins pouvoirs à Pétain, qui fonde l'« État français »."},{"id":160,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel régime remplace la IIIe République en juillet 1940 ?","c":["La IVe République","Le Gouvernement provisoire de la République française","Le Comité français de libération nationale","L'État français, dirigé par le maréchal Pétain"],"a":3,"e":"Le régime de Vichy (1940-1944) abolit la devise républicaine au profit de « Travail, Famille, Patrie »."},{"id":161,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle base navale française est bombardée par la Royal Navy le 3 juillet 1940 ?","c":["Mers el-Kébir","Dakar","Toulon","Bizerte"],"a":0,"e":"Craignant que la flotte ne tombe aux mains de l'Allemagne, les Britanniques bombardent Mers el-Kébir : près de 1 300 marins français sont tués."},{"id":162,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Comment appelle-t-on la grande arrestation de Juifs organisée à Paris les 16 et 17 juillet 1942 ?","c":["La rafle des enfants d'Izieu","La rafle du Vél' d'Hiv","La nuit de Cristal","La rafle du Vieux-Port"],"a":1,"e":"Plus de 13 000 Juifs sont arrêtés par la police française et regroupés au Vélodrome d'Hiver ou internés à Drancy avant leur déportation. La nuit de Cristal a lieu en Allemagne en 1938."},{"id":163,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle bataille de 1942, menée en Libye par les Forces françaises libres du général Koenig, a donné son nom à un pont parisien ?","c":["Tobrouk","Koufra","Bir Hakeim","El-Alamein"],"a":2,"e":"En mai-juin 1942, les FFL résistent seize jours à Bir Hakeim face à Rommel."},{"id":164,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Où la flotte française se saborde-t-elle le 27 novembre 1942 pour échapper aux Allemands ?","c":["À Cherbourg","À Mers el-Kébir","À Brest","À Toulon"],"a":3,"e":"Après l'invasion de la zone sud, plus de 90 navires se sabordent dans la rade de Toulon."},{"id":165,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Qu'est-ce que le STO instauré en 1943 ?","c":["La Section technique d'occupation","Le Service de transport ouvrier","Le Service du travail obligatoire en Allemagne","Le Service des troupes d'outre-mer"],"a":2,"e":"Créé en février 1943, le STO envoie des centaines de milliers de jeunes Français travailler en Allemagne ; beaucoup de réfractaires rejoignent les maquis."},{"id":166,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel ancien préfet, envoyé par de Gaulle, unifie la Résistance intérieure et préside le Conseil national de la Résistance en 1943 ?","c":["Jean Moulin","Henri Frenay","Georges Bidault","Pierre Brossolette"],"a":0,"e":"Jean Moulin préside la première réunion du CNR le 27 mai 1943 ; arrêté à Caluire, il meurt en juillet 1943. Bidault lui succède."},{"id":167,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"À quelle date a lieu le débarquement allié en Normandie ?","c":["8 novembre 1942","6 juin 1944","15 août 1944","25 août 1944"],"a":1,"e":"Le D-Day a lieu le 6 juin 1944. 8 novembre 1942 : débarquement en Afrique du Nord ; 15 août 1944 : débarquement de Provence ; 25 août 1944 : libération de Paris."},{"id":168,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Où a lieu le débarquement allié du 15 août 1944, auquel participe l'armée française du général de Lattre ?","c":["En Bretagne","En Normandie","En Corse","En Provence"],"a":3,"e":"Le débarquement de Provence (opération Dragoon) libère rapidement Toulon et Marseille. La Corse avait été libérée dès 1943."},{"id":169,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel général commande la 2e division blindée qui libère Paris en août 1944 ?","c":["Jean de Lattre de Tassigny","Leclerc","Alphonse Juin","Marie-Pierre Koenig"],"a":1,"e":"Philippe Leclerc de Hauteclocque entre dans Paris le 24-25 août 1944 ; il avait juré à Koufra (1941) de libérer Strasbourg, ce qu'il fait en novembre 1944."},{"id":170,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quel village de Haute-Vienne est détruit et sa population massacrée par une division SS le 10 juin 1944 ?","c":["Ascq","Tulle","Maillé","Oradour-sur-Glane"],"a":3,"e":"643 habitants sont tués par la division Das Reich. La veille, 99 hommes avaient été pendus à Tulle, en Corrèze."},{"id":171,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"En quelle année les femmes obtiennent-elles le droit de vote en France ?","c":["1919","1936","1944","1958"],"a":2,"e":"L'ordonnance du 21 avril 1944 accorde le droit de vote aux femmes, qui votent pour la première fois aux municipales du 29 avril 1945."},{"id":172,"m":"cg","t":"Histoire de France","s":"Guerres mondiales (1914-1945)","q":"Quelle date commémore en France la victoire de 1945 sur l'Allemagne nazie ?","c":["Le 8 mai","Le 18 juin","Le 6 juin","Le 11 novembre"],"a":0,"e":"La capitulation allemande prend effet le 8 mai 1945. Le 11 novembre commémore l'armistice de 1918."},{"id":173,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année les ordonnances créant la Sécurité sociale sont-elles signées ?","c":["1936","1945","1958","1968"],"a":1,"e":"Les ordonnances des 4 et 19 octobre 1945 mettent en œuvre le programme du Conseil national de la Résistance."},{"id":174,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel ministre communiste du Travail est associé à la mise en place de la Sécurité sociale en 1946 ?","c":["Ambroise Croizat","Pierre Mendès France","Maurice Thorez","Jean Monnet"],"a":0,"e":"Ministre du Travail de 1945 à 1947, Ambroise Croizat met en place le régime général avec le haut fonctionnaire Pierre Laroque."},{"id":175,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année la Constitution de la IVe République est-elle adoptée ?","c":["1944","1946","1954","1958"],"a":1,"e":"Approuvée par référendum le 13 octobre 1946 et promulguée le 27 octobre ; son préambule reste en vigueur aujourd'hui."},{"id":176,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Comment s'appelle le programme d'aide américaine à la reconstruction de l'Europe lancé en 1947 ?","c":["La doctrine Truman","Le plan Monnet","Le plan Marshall","Le plan Schuman"],"a":2,"e":"Annoncé par le secrétaire d'État George Marshall en juin 1947. Le plan Monnet est le premier plan français de modernisation."},{"id":177,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Comment appelle-t-on la période de croissance économique qu'a connue la France entre 1947 et 1973 ?","c":["Les 20 piteuses","Les 25 savoureuses","Les 30 glorieuses","Les sixties"],"a":2,"e":"L'expression « Trente Glorieuses » est due à l'économiste Jean Fourastié (1979) ; la période s'achève avec le premier choc pétrolier.","o":"Annales 2025 · Q20"},{"id":178,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quelle défaite militaire de 1954 précipite la fin de la guerre d'Indochine ?","c":["Diên Biên Phu","Cao Bang","Lang Son","Na San"],"a":0,"e":"Le camp retranché de Diên Biên Phu tombe le 7 mai 1954 ; les accords de Genève sont signés en juillet."},{"id":179,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel président du Conseil négocie les accords de Genève qui mettent fin à la guerre d'Indochine en 1954 ?","c":["Pierre Mendès France","Antoine Pinay","René Coty","Guy Mollet"],"a":0,"e":"Mendès France s'était engagé à obtenir la paix en un mois ; les accords sont signés le 21 juillet 1954."},{"id":180,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quelle date marque le début de la guerre d'Algérie (« Toussaint rouge ») ?","c":["8 mai 1945","1er novembre 1954","13 mai 1958","19 mars 1962"],"a":1,"e":"Le FLN commet une série d'attentats le 1er novembre 1954. 8 mai 1945 : massacres de Sétif ; 13 mai 1958 : crise d'Alger ; 19 mars 1962 : cessez-le-feu."},{"id":181,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quels accords de 1962 mettent fin à la guerre d'Algérie ?","c":["Les accords de Grenelle","Les accords de Matignon","Les accords de Genève","Les accords d'Évian"],"a":3,"e":"Signés le 18 mars 1962, ils sont approuvés par référendum ; l'Algérie devient indépendante le 5 juillet 1962."},{"id":182,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Dans quelle ville le général de Gaulle lance-t-il « Je vous ai compris ! » le 4 juin 1958 ?","c":["Constantine","Mostaganem","Alger","Oran"],"a":2,"e":"Le discours est prononcé au Forum d'Alger. À Mostaganem, le 6 juin, il lance « Vive l'Algérie française ! »."},{"id":183,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel président de la IVe République fait appel au général de Gaulle en mai 1958 ?","c":["René Coty","Pierre Pflimlin","Vincent Auriol","Félix Gaillard"],"a":0,"e":"René Coty appelle « le plus illustre des Français » ; de Gaulle est investi président du Conseil le 1er juin 1958."},{"id":184,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année la plupart des colonies françaises d'Afrique subsaharienne accèdent-elles à l'indépendance ?","c":["1946","1956","1960","1962"],"a":2,"e":"En 1960, quatorze anciennes colonies françaises d'Afrique deviennent indépendantes (Sénégal, Côte d'Ivoire, Madagascar…)."},{"id":185,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel traité de coopération franco-allemande est signé en 1963 par de Gaulle et Adenauer ?","c":["Le traité de Rome","Le traité de Paris","Le traité d'Aix-la-Chapelle","Le traité de l'Élysée"],"a":3,"e":"Signé le 22 janvier 1963, il scelle la réconciliation franco-allemande ; le traité d'Aix-la-Chapelle (2019) le complète."},{"id":186,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année a lieu la première élection présidentielle au suffrage universel direct sous la Ve République ?","c":["1958","1962","1965","1969"],"a":2,"e":"La réforme est adoptée par référendum en 1962 ; en décembre 1965, de Gaulle est réélu face à François Mitterrand au second tour."},{"id":187,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quels accords, négociés en mai 1968, prévoient notamment une hausse de 35 % du salaire minimum ?","c":["Les accords de Matignon","Les accords de Grenelle","Les accords d'Évian","Les accords de Nouméa"],"a":1,"e":"Négociés au ministère du Travail, rue de Grenelle, les 25-27 mai 1968, ils portent le SMIG de 2,22 à 3 francs de l'heure."},{"id":188,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Pourquoi le général de Gaulle quitte-t-il le pouvoir en avril 1969 ?","c":["Pour raisons de santé, au terme de son mandat","Après l'échec du référendum sur la régionalisation et la réforme du Sénat","À la suite des grèves de mai 1968, dès le mois de juin","Après sa défaite au second tour de l'élection présidentielle"],"a":1,"e":"Le « non » l'emporte le 27 avril 1969 avec 52,4 % ; de Gaulle démissionne le lendemain. Il meurt en novembre 1970."},{"id":189,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel président de la République meurt en cours de mandat en 1974 ?","c":["Valéry Giscard d'Estaing","Charles de Gaulle","Georges Pompidou","René Coty"],"a":2,"e":"Georges Pompidou meurt le 2 avril 1974 ; Alain Poher assure l'intérim, puis Valéry Giscard d'Estaing est élu."},{"id":190,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année l'âge de la majorité civile est-il abaissé de 21 à 18 ans ?","c":["1945","1968","1974","1981"],"a":2,"e":"Loi du 5 juillet 1974, l'une des premières réformes du président Giscard d'Estaing."},{"id":191,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quelle ministre de la Santé défend la loi dépénalisant l'interruption volontaire de grossesse, promulguée en 1975 ?","c":["Simone Veil","Yvette Roudy","Gisèle Halimi","Françoise Giroud"],"a":0,"e":"La loi Veil est promulguée le 17 janvier 1975. Depuis 2024, la liberté de recourir à l'IVG figure dans la Constitution."},{"id":192,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Laquelle de ces personnalités est associée à l'abolition de la peine de mort ?","c":["Robert BADINTER","Jacques CHIRAC","Valéry GISCARD D'ESTAING","Simone VEIL"],"a":0,"e":"Garde des Sceaux de François Mitterrand, Robert Badinter fait voter l'abolition (loi du 9 octobre 1981) ; il entre au Panthéon en 2025.","o":"Annales 2024 · Q25"},{"id":193,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Qui est le premier président de gauche élu sous la Ve République ?","c":["François Mitterrand","Pierre Mauroy","François Hollande","Lionel Jospin"],"a":0,"e":"François Mitterrand est élu le 10 mai 1981 face à Valéry Giscard d'Estaing, puis réélu en 1988."},{"id":194,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Qui est le Premier ministre de la première cohabitation, en 1986 ?","c":["Jacques Chirac","Lionel Jospin","Michel Rocard","Édouard Balladur"],"a":0,"e":"De 1986 à 1988, Jacques Chirac gouverne avec François Mitterrand. Balladur (1993) et Jospin (1997) dirigent les deux cohabitations suivantes."},{"id":195,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Qui est la première femme nommée Premier ministre en France, en 1991 ?","c":["Édith Cresson","Élisabeth Borne","Ségolène Royal","Martine Aubry"],"a":0,"e":"Édith Cresson est Première ministre de mai 1991 à avril 1992. Élisabeth Borne est la deuxième (2022-2024)."},{"id":196,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année les Français approuvent-ils par référendum le traité de Maastricht ?","c":["1986","1992","2000","2005"],"a":1,"e":"Le « oui » l'emporte de justesse (51 %) le 20 septembre 1992. En 2005, les Français rejettent le traité constitutionnel européen."},{"id":197,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Depuis quand les pièces et billets en euros circulent-ils en France ?","c":["1er janvier 1992","1er janvier 1999","1er janvier 2002","1er janvier 2005"],"a":2,"e":"L'euro existe comme monnaie scripturale depuis 1999 ; les espèces arrivent le 1er janvier 2002, et le franc disparaît le 17 février 2002."},{"id":198,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quel président annonce en 1996 la professionnalisation des armées et la suspension du service national ?","c":["François Mitterrand","Valéry Giscard d'Estaing","Jacques Chirac","Nicolas Sarkozy"],"a":2,"e":"La loi de 1997 suspend l'appel sous les drapeaux ; elle crée la journée d'appel de préparation à la défense, devenue la JDC."},{"id":199,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"En quelle année le pacte civil de solidarité (Pacs) est-il créé ?","c":["1981","1993","1999","2013"],"a":2,"e":"Le Pacs est créé par la loi du 15 novembre 1999. Le mariage pour tous date de 2013."},{"id":200,"m":"cg","t":"Histoire de France","s":"La France depuis 1945","q":"Quelle garde des Sceaux porte la loi ouvrant le mariage aux couples de même sexe en 2013 ?","c":["Marisol Touraine","Rachida Dati","Najat Vallaud-Belkacem","Christiane Taubira"],"a":3,"e":"La loi du 17 mai 2013 est défendue par Christiane Taubira, ministre de la Justice."},{"id":201,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quelle est la date de la Constitution de la Ve République ?","c":["27 octobre 1946","28 septembre 1958","4 octobre 1958","6 novembre 1962"],"a":2,"e":"Approuvée par référendum le 28 septembre 1958, la Constitution est promulguée le 4 octobre 1958, date qu'elle porte."},{"id":202,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Selon l'article 1er de la Constitution, la France est une République indivisible, laïque, démocratique et…","c":["sociale","fédérale","solidaire","fraternelle"],"a":0,"e":"Article 1er : « La France est une République indivisible, laïque, démocratique et sociale. »"},{"id":203,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Selon l'article 2 de la Constitution, quel est l'emblème national ?","c":["Marianne","Le drapeau tricolore, bleu, blanc, rouge","Le faisceau de licteur","Le coq gaulois"],"a":1,"e":"L'article 2 fixe la langue (le français), l'emblème (le drapeau tricolore), l'hymne (La Marseillaise), la devise et le principe de la République."},{"id":204,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"En France, au titre de quelles élections présidentielles le quinquennat s'applique-t-il pour la première fois ?","c":["1959","1981","2002","2007"],"a":2,"e":"Adopté par référendum en septembre 2000, le quinquennat s'applique dès l'élection de 2002 (réélection de Jacques Chirac).","o":"Annales 2022 · Q29"},{"id":205,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Depuis la révision constitutionnelle de 2008, combien de mandats présidentiels consécutifs une même personne peut-elle exercer ?","c":["1","2","3","Aucune limite"],"a":1,"e":"L'article 6 dispose que « nul ne peut exercer plus de deux mandats consécutifs »."},{"id":206,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Qui assure l'intérim en cas de décès ou de démission du président de la République ?","c":["Le ou la ministre de l'Intérieur et des Outre-mer","Le ou la ministre des Armées","Le ou la président(e) de l'Assemblée nationale","Le ou la président(e) du Sénat"],"a":3,"e":"Article 7 : l'intérim est exercé par le président du Sénat (Alain Poher l'a fait en 1969 et en 1974).","o":"Annales 2024 · Q17"},{"id":207,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Qui nomme le Premier ministre ?","c":["Le Conseil constitutionnel","Le Sénat","L'Assemblée nationale","Le président de la République"],"a":3,"e":"Article 8 : le président nomme le Premier ministre et, sur sa proposition, les autres membres du gouvernement."},{"id":208,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quel article de la Constitution permet au gouvernement de faire adopter un texte sans vote, sauf si une motion de censure est adoptée ?","c":["L'article 11","L'article 16","L'article 49, alinéa 3","L'article 89"],"a":2,"e":"Le « 49.3 » engage la responsabilité du gouvernement ; depuis 2008, il est limité aux textes budgétaires et à un autre texte par session."},{"id":209,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quel article de la Constitution confère des pouvoirs exceptionnels au président de la République en cas de menace grave et immédiate ?","c":["L'article 49","L'article 89","L'article 16","L'article 34"],"a":2,"e":"L'article 16 n'a été utilisé qu'une fois, en 1961, après le putsch des généraux à Alger."},{"id":210,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Lorsque le Parlement est réuni en Congrès pour réviser la Constitution, quelle majorité est requise ?","c":["Les deux tiers des suffrages exprimés","La majorité absolue des membres","Les trois cinquièmes des suffrages exprimés","La majorité simple des suffrages exprimés"],"a":2,"e":"Article 89 : le projet de révision n'est approuvé par le Congrès que s'il réunit la majorité des trois cinquièmes des suffrages exprimés."},{"id":211,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Où se réunit le Parlement en Congrès ?","c":["Au palais Bourbon","Au palais de l'Élysée","Au palais du Luxembourg","Au château de Versailles"],"a":3,"e":"Députés et sénateurs (925 parlementaires) se réunissent dans l'aile du Midi du château de Versailles."},{"id":212,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Combien de membres nommés compte le Conseil constitutionnel ?","c":["7","9","12","15"],"a":1,"e":"Neuf membres nommés pour neuf ans (trois par le président de la République, trois par chaque président d'assemblée), renouvelés par tiers tous les trois ans."},{"id":213,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Que permet la question prioritaire de constitutionnalité (QPC), en vigueur depuis 2010 ?","c":["Bloquer définitivement une loi votée par l'Assemblée nationale","Consulter le Conseil d'État avant l'organisation d'un référendum","Saisir directement la Cour de justice de l'Union européenne","Contester, au cours d'un procès, la conformité d'une loi aux droits garantis par la Constitution"],"a":3,"e":"Créée par la révision de 2008 (article 61-1), la QPC permet à tout justiciable de faire contrôler une loi déjà en vigueur."},{"id":214,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Combien de députés ou de sénateurs faut-il au minimum pour saisir le Conseil constitutionnel d'une loi avant sa promulgation ?","c":["30","60","100","185"],"a":1,"e":"Depuis la révision de 1974, soixante députés ou soixante sénateurs peuvent saisir le Conseil constitutionnel."},{"id":215,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Devant qui le gouvernement est-il politiquement responsable ?","c":["Le Parlement réuni en Congrès","Le Conseil économique, social et environnemental","Le Sénat","L'Assemblée nationale"],"a":3,"e":"Seule l'Assemblée nationale peut renverser le gouvernement par une motion de censure (article 49)."},{"id":216,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quel pouvoir le président de la République détient-il à l'égard de l'Assemblée nationale (article 12) ?","c":["Il peut révoquer les députés","Il peut annuler ses lois","Il peut la dissoudre","Il en nomme le président"],"a":2,"e":"Après consultation du Premier ministre et des présidents des assemblées, le président peut prononcer la dissolution (par exemple en juin 2024)."},{"id":217,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Selon la Constitution, qui est le chef des armées ?","c":["Le président de la République","Le ministre des Armées","Le chef d'état-major des armées","Le Premier ministre"],"a":0,"e":"Article 15 : « Le Président de la République est le chef des armées. » Le Premier ministre est responsable de la défense nationale (article 21)."},{"id":218,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Dans quel délai le président de la République doit-il promulguer une loi après sa transmission au gouvernement ?","c":["8 jours","15 jours","1 mois","3 mois"],"a":1,"e":"Article 10 : la promulgation intervient dans les quinze jours ; le président peut demander une nouvelle délibération."},{"id":219,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quel texte n'est pas mentionné par le préambule de la Constitution de 1958 ?","c":["Le Code civil de 1804","La Déclaration des droits de l'homme et du citoyen de 1789","Le préambule de la Constitution de 1946","La Charte de l'environnement de 2004"],"a":0,"e":"Le préambule renvoie à la DDHC, au préambule de 1946 et à la Charte de l'environnement, qui forment avec la Constitution le « bloc de constitutionnalité »."},{"id":220,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Quelle institution constitutionnelle, siégeant au palais d'Iéna, représente la société civile ?","c":["Le Défenseur des droits","La Cour des comptes","Le Conseil d'État","Le Conseil économique, social et environnemental"],"a":3,"e":"Le CESE, souvent appelé la « troisième assemblée », rend des avis et peut être saisi par voie de pétition."},{"id":221,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Qu'implique la laïcité en France ?","c":["Elle implique que les citoyens doivent pratiquer une religion spécifique","Elle implique la séparation de l'État et des organisations religieuses","Elle implique que l'État impose une religion officielle","La loi de 1905 sur la séparation de l'Église et de l'État n'est plus en vigueur"],"a":1,"e":"La laïcité garantit la liberté de conscience et la neutralité de l'État ; la loi de 1905 est toujours en vigueur.","o":"Sujet zéro 2026 · Q13"},{"id":222,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Qu'est-ce qu'une démocratie ?","c":["Un système politique dans lequel les décisions sont prises par un conseil d'experts","Un système politique dans lequel le peuple est souverain","Un système politique où l'obéissance est imposée par la répression","Un système politique où le pouvoir est détenu par un roi"],"a":1,"e":"Article 3 de la Constitution : « La souveraineté nationale appartient au peuple qui l'exerce par ses représentants et par la voie du référendum. »","o":"Sujet zéro 2026 · Q16"},{"id":223,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Trouvez le mot qui manque dans cet extrait de l'article 4 de la DDHC : « La … consiste à pouvoir faire tout ce qui ne nuit pas à autrui ».","c":["Conscience","Liberté","Fraternité","Politique"],"a":1,"e":"Article 4 de la Déclaration de 1789 : « La liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui. »","o":"Sujet zéro 2026 · Q17"},{"id":224,"m":"cg","t":"Institutions","s":"Constitution et Ve République","q":"Qu'est-ce que la JDC (Journée de défense et de citoyenneté) ?","c":["Une activité de loisirs pour les jeunes","Un examen médical obligatoire","Un jour de congé pour les élèves","Une journée de formation sur la défense nationale"],"a":3,"e":"Obligatoire entre 16 et 25 ans, la JDC présente les enjeux de la défense ; son certificat est exigé pour s'inscrire aux concours et examens publics.","o":"Sujet zéro 2026 · Q18"},{"id":225,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quel est le rôle du Parlement français ?","c":["Il dirige l'administration publique","Il nomme le Premier ministre","Il représente la France à l'étranger","Il vote les lois"],"a":3,"e":"Article 24 : le Parlement vote la loi, contrôle l'action du gouvernement et évalue les politiques publiques.","o":"Sujet zéro 2026 · Q15"},{"id":226,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Combien de députés siègent à l'Assemblée nationale ?","c":["348","577","600","925"],"a":1,"e":"577 députés élus pour cinq ans au scrutin majoritaire à deux tours. Le Sénat compte 348 membres ; le Congrès réunit donc 925 parlementaires."},{"id":227,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Combien de sénateurs compte le Sénat ?","c":["321","348","377","577"],"a":1,"e":"Depuis 2011, le Sénat compte 348 sénateurs élus pour six ans et renouvelés par moitié tous les trois ans."},{"id":228,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quelle est la durée du mandat d'un sénateur ?","c":["5 ans","6 ans","7 ans","9 ans"],"a":1,"e":"Le mandat sénatorial est de six ans depuis la réforme de 2003 (il était de neuf ans auparavant)."},{"id":229,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Comment les sénateurs sont-ils élus ?","c":["Au suffrage universel direct, en même temps que les députés","Ils sont désignés par les seuls conseils régionaux","Au suffrage universel indirect, par des grands électeurs","Ils sont nommés par le président de la République"],"a":2,"e":"Le collège électoral réunit surtout des délégués des conseils municipaux, ainsi que députés, conseillers départementaux et régionaux."},{"id":230,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Dans quel bâtiment siège le Sénat ?","c":["Le palais du Luxembourg","Le Palais-Royal","Le palais Bourbon","L'hôtel de Lassay"],"a":0,"e":"Le Sénat siège au palais du Luxembourg ; l'Assemblée nationale au palais Bourbon ; le Conseil d'État et le Conseil constitutionnel au Palais-Royal."},{"id":231,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quel lieu est la résidence officielle du Premier ministre ?","c":["Le palais de l'Élysée","L'hôtel Matignon","L'hôtel de Brienne","Le palais du Luxembourg"],"a":1,"e":"L'hôtel Matignon, rue de Varenne. L'hôtel de Brienne abrite le ministère des Armées."},{"id":232,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quel article de la Constitution fixe le domaine de la loi ?","c":["L'article 16","L'article 55","L'article 34","L'article 37"],"a":2,"e":"L'article 34 énumère les matières réservées à la loi ; les autres relèvent du pouvoir réglementaire (article 37)."},{"id":233,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Selon l'article 55 de la Constitution, les traités régulièrement ratifiés ont une autorité…","c":["inférieure à celle des lois","égale à celle de la Constitution","supérieure à celle des lois","égale à celle des lois"],"a":2,"e":"Sous réserve de réciprocité, les traités l'emportent sur les lois mais restent soumis à la Constitution."},{"id":234,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"En droit français, quel est l'ordre dans lequel s'imposent les textes suivants ?","c":["Circulaire, décret, loi","Circulaire, loi, décret","Loi, circulaire, décret","Loi, décret, circulaire"],"a":3,"e":"Hiérarchie des normes : Constitution, traités, loi, règlements (décrets, arrêtés), puis circulaires d'interprétation.","o":"Annales 2021 · Q31"},{"id":235,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"En cas de désaccord entre les deux assemblées sur un texte, quel organe peut être réuni pour proposer une rédaction commune ?","c":["Le Congrès","Le Conseil constitutionnel","Une commission mixte paritaire","Une commission d'enquête"],"a":2,"e":"La CMP réunit sept députés et sept sénateurs (article 45)."},{"id":236,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"En cas de désaccord persistant entre les deux chambres, laquelle peut avoir le « dernier mot » à la demande du gouvernement ?","c":["Le Conseil constitutionnel","Le Conseil d'État","Le Sénat","L'Assemblée nationale"],"a":3,"e":"Après échec de la CMP, le gouvernement peut demander à l'Assemblée nationale de statuer définitivement (sauf pour les lois organiques relatives au Sénat et les révisions constitutionnelles)."},{"id":237,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quelle loi organique de 2001 encadre la préparation et l'exécution du budget de l'État ?","c":["La loi Sapin II","La loi NOTRe","La loi ESSOC","La LOLF"],"a":3,"e":"La loi organique relative aux lois de finances (LOLF) du 1er août 2001 organise le budget en missions, programmes et actions, avec des indicateurs de performance."},{"id":238,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Comment appelle-t-on un texte de loi déposé par un député ou un sénateur ?","c":["Une ordonnance","Une proposition de loi","Un projet de loi","Un décret"],"a":1,"e":"L'initiative des lois appartient concurremment au Premier ministre (projets de loi) et aux parlementaires (propositions de loi)."},{"id":239,"m":"cg","t":"Institutions","s":"Parlement et loi","q":"Quel acte permet au gouvernement, habilité par le Parlement, de prendre des mesures relevant normalement de la loi ?","c":["L'arrêté préfectoral","Le décret simple","La circulaire","L'ordonnance"],"a":3,"e":"Article 38 : les ordonnances doivent ensuite être ratifiées par le Parlement pour acquérir valeur législative."},{"id":240,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Dans le système juridique français, quel est le rôle des procureurs de la République ?","c":["Décider de l'opportunité des poursuites","Défendre les justiciables","Incarcérer les condamnés","Prononcer les condamnations"],"a":0,"e":"Magistrats du parquet, les procureurs reçoivent les plaintes et décident de poursuivre, de classer ou de recourir à une alternative aux poursuites.","o":"Annales 2022 · Q20"},{"id":241,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Laquelle de ces situations ne relève pas de la compétence du Défenseur des droits ?","c":["Absence de contrat de travail","Non-réintégration sur le poste au retour de congé maternité","Refus d'embauche sur un poste d'accueil en raison de l'orientation sexuelle du demandeur","Sur un vol aérien, refus d'embarquer une personne pour cause d'obésité"],"a":0,"e":"Les trois autres cas sont des discriminations, qui relèvent du Défenseur des droits ; l'absence de contrat de travail relève de l'inspection du travail et des prud'hommes.","o":"Annales 2021 · Q21"},{"id":242,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle est la plus haute juridiction de l'ordre administratif ?","c":["La Cour des comptes","La Cour de cassation","Le Conseil d'État","Le Conseil constitutionnel"],"a":2,"e":"Le Conseil d'État juge en dernier ressort les litiges avec l'administration et conseille le gouvernement sur ses projets de texte."},{"id":243,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle juridiction se trouve au sommet de l'ordre judiciaire ?","c":["Le Conseil d'État","La cour d'appel de Paris","La Cour de cassation","Le Conseil constitutionnel"],"a":2,"e":"La Cour de cassation ne rejuge pas les faits : elle vérifie la bonne application du droit par les juridictions civiles et pénales."},{"id":244,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle juridiction règle les litiges individuels entre salariés et employeurs nés du contrat de travail ?","c":["La cour d'assises","Le conseil de prud'hommes","Le tribunal de commerce","Le tribunal administratif"],"a":1,"e":"Les prud'hommes sont composés à parité de conseillers représentant les salariés et les employeurs."},{"id":245,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle juridiction juge les crimes avec la participation de jurés populaires tirés au sort ?","c":["La cour d'assises","Le tribunal de police","Le conseil de prud'hommes","Le tribunal correctionnel"],"a":0,"e":"La cour d'assises réunit trois magistrats et six jurés en premier ressort ; certains crimes relèvent désormais des cours criminelles départementales, sans jurés."},{"id":246,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle juridiction juge les délits, comme le vol ou l'escroquerie ?","c":["Le tribunal correctionnel","La cour d'assises","Le tribunal de police","Le conseil de prud'hommes"],"a":0,"e":"Le tribunal correctionnel juge les délits ; le tribunal de police juge les contraventions de 5e classe."},{"id":247,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Comment se classent les trois catégories d'infractions pénales, de la moins grave à la plus grave ?","c":["Contravention, délit, crime","Délit, contravention, crime","Contravention, crime, délit","Crime, délit, contravention"],"a":0,"e":"Le Code pénal distingue contraventions (tribunal de police), délits (tribunal correctionnel) et crimes (cour d'assises)."},{"id":248,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle autorité administrative indépendante veille à la protection des données personnelles en France ?","c":["L'Arcom","La CNIL","L'Autorité de la concurrence","La HATVP"],"a":1,"e":"La Commission nationale de l'informatique et des libertés est créée par la loi du 6 janvier 1978."},{"id":249,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Depuis quelle année le règlement général sur la protection des données (RGPD) s'applique-t-il dans l'Union européenne ?","c":["2008","2014","2018","2022"],"a":2,"e":"Le RGPD, adopté en 2016, est applicable depuis le 25 mai 2018."},{"id":250,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quelle institution, créée par la révision constitutionnelle de 2008, remplace notamment le Médiateur de la République et la HALDE ?","c":["Le Défenseur des droits","Le Conseil économique, social et environnemental","La CNIL","La Cour de justice de la République"],"a":0,"e":"Installé en 2011, le Défenseur des droits défend les droits des usagers des services publics, des enfants et les victimes de discriminations."},{"id":251,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quel principe garantit que nul ne peut être puni pour un acte qui n'était pas une infraction au moment où il a été commis ?","c":["La non-rétroactivité de la loi pénale plus sévère","La présomption d'innocence","Le droit à un procès équitable","L'autorité de la chose jugée"],"a":0,"e":"Article 8 de la DDHC : nul ne peut être puni qu'en vertu d'une loi « établie et promulguée antérieurement au délit »."},{"id":252,"m":"cg","t":"Institutions","s":"Justice et droits","q":"Quel texte reconnaît le droit de grève « dans le cadre des lois qui le réglementent » ?","c":["Le préambule de la Constitution de 1946","La Déclaration des droits de l'homme de 1789","La loi Le Chapelier de 1791","Le traité de Rome de 1957"],"a":0,"e":"Le préambule de 1946 consacre aussi le droit syndical ; le Conseil d'État a reconnu le droit de grève des fonctionnaires dès 1950 (arrêt Dehaene)."},{"id":253,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quelles sont les trois catégories de collectivités territoriales de droit commun ?","c":["L'arrondissement, le département et la région","La commune, l'intercommunalité et l'État","La commune, le canton et la région","La commune, le département et la région"],"a":3,"e":"Article 72 de la Constitution. Le canton et l'arrondissement sont de simples circonscriptions administratives ou électorales."},{"id":254,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Combien de régions compte la France métropolitaine depuis le 1er janvier 2016 ?","c":["12","13","18","22"],"a":1,"e":"La loi de 2015 ramène les régions métropolitaines de 22 à 13 (Corse comprise) ; avec les 5 régions d'outre-mer, on en compte 18."},{"id":255,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Qui représente l'État dans le département ?","c":["Le président du conseil départemental","Le préfet","Le maire du chef-lieu","Le député de la circonscription"],"a":1,"e":"Le préfet, nommé en conseil des ministres, est le représentant de chacun des membres du gouvernement et contrôle la légalité des actes locaux."},{"id":256,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Par qui le maire est-il élu ?","c":["Par le conseil municipal","Par le conseil départemental","Directement par les habitants de la commune","Par le préfet"],"a":0,"e":"Les électeurs élisent les conseillers municipaux, qui élisent ensuite le maire et ses adjoints."},{"id":257,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quelle est la durée du mandat des conseillers municipaux ?","c":["4 ans","5 ans","6 ans","7 ans"],"a":2,"e":"Les conseillers municipaux, départementaux et régionaux sont élus pour six ans."},{"id":258,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quel ministre de l'Intérieur porte les lois de décentralisation de 1982 ?","c":["Jean-Pierre Chevènement","Pierre Joxe","Charles Pasqua","Gaston Defferre"],"a":3,"e":"La loi du 2 mars 1982 supprime la tutelle préfectorale a priori et transfère l'exécutif départemental et régional à des élus."},{"id":259,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quelle collectivité est chargée de la construction et de l'entretien des collèges ?","c":["Le département","L'intercommunalité","La région","La commune"],"a":0,"e":"Les communes gèrent les écoles, les départements les collèges, les régions les lycées."},{"id":260,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quelle collectivité est « chef de file » de l'action sociale et de la solidarité ?","c":["Le département","La métropole","La commune","La région"],"a":0,"e":"Le département gère notamment l'aide sociale à l'enfance, l'allocation personnalisée d'autonomie et le RSA."},{"id":261,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Combien de communes la France compte-t-elle environ en 2025 ?","c":["environ 3 500","environ 15 000","environ 35 000","environ 50 000"],"a":2,"e":"La France compte un peu moins de 35 000 communes, un record en Europe malgré les fusions de communes nouvelles."},{"id":262,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Combien de départements compte la France, métropole et outre-mer compris ?","c":["95","96","101","103"],"a":2,"e":"96 départements métropolitains (dont la Corse-du-Sud et la Haute-Corse) et 5 d'outre-mer."},{"id":263,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quel territoire devient le 101e département français en 2011 ?","c":["Saint-Martin","La Nouvelle-Calédonie","Mayotte","La Guyane"],"a":2,"e":"Après le référendum de 2009, Mayotte devient département le 31 mars 2011."},{"id":264,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Quel accord de 1998 organise l'avenir institutionnel de la Nouvelle-Calédonie ?","c":["L'accord de Papeete","Les accords d'Évian","Les accords de Matignon","L'accord de Nouméa"],"a":3,"e":"L'accord de Nouméa (5 mai 1998) prolonge les accords de Matignon-Oudinot (1988) et prévoit des transferts de compétences et des consultations sur l'indépendance."},{"id":265,"m":"cg","t":"Institutions","s":"Collectivités territoriales","q":"Qui crée le corps des préfets en 1800 ?","c":["Louis XIV","Gaston Defferre","Charles de Gaulle","Napoléon Bonaparte"],"a":3,"e":"La loi du 28 pluviôse an VIII (17 février 1800) place un préfet à la tête de chaque département."},{"id":266,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"La Cour de justice de l'Union européenne est installée à :","c":["Bruxelles","La Haye","Luxembourg","Strasbourg"],"a":2,"e":"La CJUE siège à Luxembourg. Strasbourg accueille la Cour européenne des droits de l'homme (Conseil de l'Europe), La Haye la Cour internationale de justice.","o":"Annales 2021 · Q20"},{"id":267,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Lequel de ces pays ne fait pas partie de la zone euro ?","c":["L'Allemagne","La France","La Lituanie","La Suisse"],"a":3,"e":"La Suisse n'est pas membre de l'Union européenne et utilise le franc suisse. La Lituanie a adopté l'euro en 2015.","o":"Annales 2022 · Q21"},{"id":268,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Parmi les pays suivants, lequel est membre de l'Union européenne ?","c":["Albanie","Bulgarie","Moldavie","Norvège"],"a":1,"e":"La Bulgarie est membre de l'UE depuis 2007. L'Albanie et la Moldavie sont candidates ; la Norvège a refusé l'adhésion par référendum.","o":"Annales 2023 · Q26"},{"id":269,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quel État membre assure la présidence du Conseil de l'Union européenne du 1er juillet au 31 décembre 2024 ?","c":["L'Autriche","La Belgique","La France","La Hongrie"],"a":3,"e":"La présidence tournante change tous les six mois : Belgique au 1er semestre 2024, Hongrie au 2nd semestre 2024.","o":"Annales 2024 · Q30"},{"id":270,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Qu'est-ce que le « Digital Services Act (DSA) » ?","c":["Un nouveau programme éducatif qui sera déployé dans tous les lycées français à l'horizon 2030","Un nouveau protocole de paiement en ligne sécurisé initié par les banques européennes","Un nouveau règlement européen sur les services numériques qui encadre les activités des plateformes, en particulier celles des GAFAM","Une nouvelle obligation pour l'administration de digitaliser tous les formulaires ou actes à l'horizon 2030"],"a":2,"e":"Le règlement sur les services numériques (DSA) s'applique pleinement depuis février 2024 ; il impose aux plateformes la lutte contre les contenus illicites.","o":"Annales 2024 · Q22"},{"id":271,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Qu'est-ce que l'espace Schengen ?","c":["Un espace avec des contrôles à chaque frontière intérieure","Un espace de libre circulation des personnes","Un programme spatial européen","Un système bancaire sécurisé"],"a":1,"e":"Issu des accords de Schengen (1985), il supprime les contrôles aux frontières intérieures entre les États participants.","o":"Annales 2025 · Q17"},{"id":272,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Qui est devenue la première femme présidente de la Banque centrale européenne (BCE) en 2019 ?","c":["Christine Lagarde","Angela Merkel","Ursula von der Leyen","Louise Weiss"],"a":0,"e":"Ancienne ministre de l'Économie et directrice du FMI, Christine Lagarde succède à Mario Draghi en novembre 2019.","o":"Annales 2025 · Q18"},{"id":273,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Qu'est-ce que le Brexit ?","c":["Le nom d'un futur modèle de téléphone portable","Le retrait du Royaume-Uni de l'Union européenne","Un programme informatique","Un programme spatial"],"a":1,"e":"Décidé par référendum en juin 2016, le Brexit devient effectif le 31 janvier 2020.","o":"Annales 2025 · Q30"},{"id":274,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quel traité signé en 1957 crée la Communauté économique européenne (CEE) ?","c":["Le traité de Lisbonne","Le traité de Paris","Le traité de Maastricht","Le traité de Rome"],"a":3,"e":"Les traités de Rome (25 mars 1957) créent la CEE et Euratom entre six États fondateurs."},{"id":275,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quelle communauté européenne est créée par le traité de Paris en 1951 ?","c":["La Communauté européenne du charbon et de l'acier","La Communauté européenne de l'énergie atomique","La Communauté européenne de défense","La Communauté économique européenne"],"a":0,"e":"La CECA met en commun les productions de charbon et d'acier ; la CED est rejetée par la France en 1954."},{"id":276,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quelle date est célébrée chaque année comme la « Journée de l'Europe » ?","c":["Le 25 mars","Le 9 mai","Le 1er juillet","Le 7 février"],"a":1,"e":"Le 9 mai 1950, Robert Schuman propose de mettre en commun charbon et acier. Le 25 mars rappelle les traités de Rome, le 7 février Maastricht."},{"id":277,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Lequel de ces pays ne fait pas partie des six États fondateurs de la CEE en 1957 ?","c":["Le Luxembourg","L'Italie","Le Royaume-Uni","La Belgique"],"a":2,"e":"Les six fondateurs : France, RFA, Italie, Belgique, Pays-Bas, Luxembourg. Le Royaume-Uni adhère en 1973."},{"id":278,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Combien d'États membres compte l'Union européenne en 2026 ?","c":["25","27","28","30"],"a":1,"e":"L'UE compte 27 États depuis la sortie du Royaume-Uni le 31 janvier 2020."},{"id":279,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Où se tiennent les sessions plénières mensuelles du Parlement européen, à son siège officiel ?","c":["Strasbourg","Luxembourg","Bruxelles","Francfort"],"a":0,"e":"Le siège officiel est à Strasbourg ; les commissions se réunissent à Bruxelles et le secrétariat est à Luxembourg."},{"id":280,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Dans quelle ville siège la Banque centrale européenne ?","c":["Amsterdam","Bruxelles","Francfort-sur-le-Main","Luxembourg"],"a":2,"e":"La BCE, créée en 1998, conduit la politique monétaire de la zone euro depuis Francfort."},{"id":281,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Depuis quelle année les députés européens sont-ils élus au suffrage universel direct ?","c":["1957","1979","1992","2004"],"a":1,"e":"Les premières élections européennes directes ont lieu en juin 1979 ; Simone Veil devient présidente du Parlement européen."},{"id":282,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Qui préside la Commission européenne depuis 2019 ?","c":["Kaja Kallas","Roberta Metsola","Christine Lagarde","Ursula von der Leyen"],"a":3,"e":"Ursula von der Leyen est reconduite en 2024. Roberta Metsola préside le Parlement européen."},{"id":283,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quelle juridiction, siégeant à Strasbourg, veille au respect de la Convention européenne des droits de l'homme ?","c":["La Cour pénale internationale","La Cour européenne des droits de l'homme","La Cour de justice de l'Union européenne","La Cour internationale de justice"],"a":1,"e":"La CEDH relève du Conseil de l'Europe (46 États), organisation distincte de l'Union européenne."},{"id":284,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Lequel de ces pays n'est pas membre permanent du Conseil de sécurité de l'ONU ?","c":["L'Allemagne","La Russie","La France","La Chine"],"a":0,"e":"Les cinq membres permanents, dotés d'un droit de veto, sont les États-Unis, la Russie, la Chine, la France et le Royaume-Uni."},{"id":285,"m":"cg","t":"Institutions","s":"Union européenne et international","q":"Quel traité, signé en 2007 et entré en vigueur en 2009, a réformé en dernier le fonctionnement de l'Union européenne ?","c":["Le traité d'Amsterdam","Le traité de Maastricht","Le traité de Nice","Le traité de Lisbonne"],"a":3,"e":"Le traité de Lisbonne crée notamment la présidence stable du Conseil européen et donne force juridique à la Charte des droits fondamentaux."},{"id":286,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Qu'est-ce que la TVA ?","c":["La Taxe sur les Biens et Services","La Taxe sur les Revenus","La Taxe sur la Valeur Ajoutée","La Taxe sur les Ventes et Achats"],"a":2,"e":"Impôt indirect sur la consommation, la TVA est la première recette fiscale de l'État.","o":"Sujet zéro 2026 · Q32"},{"id":287,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Qu'est-ce qu'un contrôle fiscal ?","c":["Une aide financière accordée par l'État aux entreprises en difficulté","Une opération de recouvrement des impôts impayés","Une procédure permettant aux contribuables de contester leurs impôts","Une vérification des comptes d'une entreprise ou d'un particulier par l'administration fiscale pour s'assurer de la conformité de leurs déclarations et de leurs paiements d'impôts"],"a":3,"e":"Le contrôle fiscal est la contrepartie du système déclaratif ; il est mené par la DGFiP.","o":"Sujet zéro 2026 · Q33"},{"id":288,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Qu'est-ce que le recouvrement des impôts ?","c":["La collecte des impôts","Le contrôle des entreprises","La gestion de la dette publique","La gestion des finances publiques"],"a":0,"e":"Le recouvrement consiste à encaisser l'impôt, à l'amiable ou par des procédures forcées.","o":"Sujet zéro 2026 · Q34"},{"id":289,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quel est le rôle principal de la Direction générale des douanes et droits indirects ?","c":["Collecter les impôts","Contrôler les frontières et les marchandises","Gérer la dette publique","Gérer les finances publiques"],"a":1,"e":"La DGDDI contrôle les flux de marchandises, lutte contre les trafics et perçoit certains droits indirects.","o":"Sujet zéro 2026 · Q35"},{"id":290,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Qu'est-ce qu'un tarif douanier ?","c":["Un droit de douane sur les marchandises importées","Un impôt sur les revenus","Un impôt sur les sociétés","Un impôt sur la valeur ajoutée"],"a":0,"e":"Au sein de l'UE, le tarif douanier commun s'applique aux marchandises venant de pays tiers.","o":"Sujet zéro 2026 · Q36"},{"id":291,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quelle réforme impacte les entreprises à partir du 1er septembre 2026 ?","c":["Le changement de taux de l'impôt sur les sociétés","La facturation électronique","La suppression des droits de douanes","La réforme des normes comptables"],"a":1,"e":"À partir du 1er septembre 2026, toutes les entreprises doivent pouvoir recevoir des factures électroniques ; l'obligation d'émission est progressive.","o":"Sujet zéro 2026 · Q37"},{"id":292,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Depuis le 1er mars 2022, quel texte rassemble les règles statutaires des fonctionnaires ?","c":["Le code de l'action publique","Le code du travail","Le code des relations entre le public et l'administration","Le code général de la fonction publique"],"a":3,"e":"Le CGFP codifie notamment la loi du 13 juillet 1983 (dite loi Le Pors) portant droits et obligations des fonctionnaires."},{"id":293,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quels sont les trois versants de la fonction publique ?","c":["La fonction publique centrale, déconcentrée et décentralisée","La fonction publique d'État, européenne et territoriale","L'État, la fonction publique territoriale et la fonction publique hospitalière","L'État, l'armée et la fonction publique territoriale"],"a":2,"e":"Les trois versants regroupent environ 5,7 millions d'agents."},{"id":294,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"À quelle catégorie hiérarchique appartiennent les emplois d'exécution de la fonction publique ?","c":["La catégorie A","La catégorie C","La catégorie B","La catégorie A+"],"a":1,"e":"A : conception et encadrement ; B : application et rédaction ; C : exécution. Le concours commun C des ministères économiques recrute en catégorie C."},{"id":295,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"En quelle année la DGFiP est-elle créée par la fusion de la DGI et de la DGCP ?","c":["1998","2008","2012","2019"],"a":1,"e":"La Direction générale des finances publiques naît le 3 avril 2008 de la fusion de la Direction générale des impôts et de la Direction générale de la comptabilité publique."},{"id":296,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Depuis quand le prélèvement à la source de l'impôt sur le revenu est-il en vigueur ?","c":["1er janvier 2015","1er janvier 2017","1er janvier 2019","1er janvier 2021"],"a":2,"e":"Mis en œuvre par la DGFiP, le prélèvement à la source est appliqué depuis le 1er janvier 2019."},{"id":297,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quel haut fonctionnaire est considéré comme l'inventeur de la TVA, instaurée en France en 1954 ?","c":["Jacques Rueff","Paul Delouvrier","Jean Monnet","Maurice Lauré"],"a":3,"e":"Maurice Lauré, inspecteur des finances, conçoit la TVA, ensuite adoptée par de nombreux pays."},{"id":298,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quel est le taux normal de la TVA en France métropolitaine ?","c":["5,5 %","10 %","18,6 %","20 %"],"a":3,"e":"Le taux normal est de 20 % depuis 2014 ; les taux réduits sont de 10 %, 5,5 % et 2,1 %."},{"id":299,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quelle juridiction financière, créée en 1807, contrôle la bonne utilisation de l'argent public ?","c":["La Cour de discipline budgétaire et financière","Le Conseil d'État","La Cour des comptes","L'Inspection générale des finances"],"a":2,"e":"Créée par Napoléon Ier, la Cour des comptes siège rue Cambon et assiste le Parlement et le gouvernement (article 47-2)."},{"id":300,"m":"cg","t":"Institutions","s":"Fonction publique et finances publiques","q":"Quelle obligation impose au fonctionnaire de faire preuve de retenue dans l'expression publique de ses opinions ?","c":["Le secret professionnel","L'obligation d'obéissance hiérarchique","Le devoir de discrétion professionnelle","Le devoir de réserve"],"a":3,"e":"Le devoir de réserve est d'origine jurisprudentielle ; la discrétion professionnelle concerne les faits et informations connus dans le service."},{"id":301,"m":"ma","t":"Calcul","s":"Sujet zéro 2026","q":"Un article coûte 80 euros. Il est soldé à 20 %. Quel est le prix soldé ?","c":["60 euros","64 euros","70 euros","76 euros"],"a":1,"e":"20 % de 80 = 16 ; 80 − 16 = 64 €. Raccourci : 80 × 0,8 = 64.","o":"Sujet zéro 2026 · Q38"},{"id":302,"m":"ma","t":"Calcul","s":"Sujet zéro 2026","q":"Un élève a obtenu les notes suivantes : 12, 15, 8, 10, 14. Quelle est la moyenne de ces notes ?","c":["10,80","11,80","12,80","13,80"],"a":1,"e":"Somme = 59 ; 59 ÷ 5 = 11,8.","o":"Sujet zéro 2026 · Q39"},{"id":303,"m":"ma","t":"Calcul","s":"Sujet zéro 2026","q":"Un article coûte 120 euros. Il est augmenté de 15 %. Quel est le nouveau prix ?","c":["130 euros","135 euros","138 euros","140 euros"],"a":2,"e":"15 % de 120 = 18 ; 120 + 18 = 138 €. Raccourci : 120 × 1,15.","o":"Sujet zéro 2026 · Q40"},{"id":304,"m":"ma","t":"Calcul","s":"Sujet zéro 2026","q":"Quatre influenceurs participent à une course pour soutenir Octobre rose. Voici leurs temps : Rina : 2 h 13 ; Sahirtan : 108 minutes ; Layana : 7 140 secondes ; Issa : 121 minutes. Qui est arrivé en premier ?","c":["Issa","Layana","Rina","Sahirtan"],"a":3,"e":"Tout convertir en minutes : Rina 133 ; Sahirtan 108 ; Layana 7 140 ÷ 60 = 119 ; Issa 121. Le plus petit temps : Sahirtan.","o":"Sujet zéro 2026 · Q42"},{"id":305,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Dans un élevage, 800 poules pondent en moyenne 800 œufs en 8 jours. Combien pondent 400 poules en 4 jours ?","c":["200","300","400","800"],"a":0,"e":"Moitié moins de poules : 400 œufs en 8 jours ; moitié moins de temps : 200 œufs.","o":"Sujet zéro 2026 · Q44"},{"id":306,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Sachant que le guépard parcourt 17 km en un quart d'heure, la gazelle 10 km en 10 minutes et le lion 25 km en une demi-heure, qui est le plus rapide ?","c":["La gazelle","Le guépard","Le lion","Ils courent à la même vitesse"],"a":1,"e":"Vitesses horaires : guépard 17 × 4 = 68 km/h ; gazelle 10 × 6 = 60 km/h ; lion 25 × 2 = 50 km/h.","o":"Sujet zéro 2026 · Q45"},{"id":307,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Quand Adam et Clara se sont mariés, chacun avait déjà plusieurs enfants de mariages précédents. Quelques années plus tard, il y a 8 enfants dans leur maison. Sachant qu'Adam est le père de 6 et Clara la mère de 5, combien d'enfants ont-ils eu ensemble ?","c":["3","5","6","8"],"a":0,"e":"6 + 5 = 11 liens de parenté pour 8 enfants : les 3 enfants comptés deux fois sont communs.","o":"Sujet zéro 2026 · Q46"},{"id":308,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Martin fait la queue. Le nombre de personnes est un multiple de 3 ; il y a autant de personnes devant lui que derrière lui. Deux amis sont derrière lui, aux 19e et 28e places. Quelle est la position de Martin ?","c":["14","15","16","17"],"a":3,"e":"La file compte un nombre impair (Martin au milieu), multiple de 3, d'au moins 28 personnes, avec Martin avant la 19e place : 33 personnes, Martin est 17e.","o":"Sujet zéro 2026 · Q47"},{"id":309,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Un rang a quatre sièges numérotés de 1 à 4, de gauche à droite, occupés par Lina, Idriss, Nina et Sovann. Lina n'occupe pas le siège 1 ; Idriss est directement à la droite de Lina ; Sovann n'est pas à une extrémité. À côté de qui Nina est-elle assise ?","c":["Lina et Sovann","Lina seulement","Idriss et Lina","Sovann seulement"],"a":3,"e":"Lina 2 et Idriss 3 laisseraient Sovann en bout : impossible. Donc Lina 3, Idriss 4, Sovann 2, Nina 1 : Nina n'a que Sovann à côté d'elle.","o":"Sujet zéro 2026 · Q48"},{"id":310,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"La montre de mon grand-père perd 5 minutes par heure, celle de ma grand-mère avance de 5 minutes par heure. Je les règle hier à 21 h. Ce matin, celle de mon grand-père indique 8 h. Quelle heure indique celle de ma grand-mère au même moment ?","c":["9 h","9 h 30","10 h","10 h 30"],"a":2,"e":"Le grand-père affiche 11 h écoulées à raison de 55 min par heure réelle : 12 h réelles se sont écoulées. La grand-mère affiche 12 × 65 min = 13 h après 21 h, soit 10 h.","o":"Sujet zéro 2026 · Q49"},{"id":311,"m":"ma","t":"Raisonnement logique","s":"Sujet zéro 2026","q":"Alya, Bianca et Ivy achètent chacune dix articles (crayons ou livres). Alya a acheté deux fois plus de crayons qu'Ivy de livres ; Bianca deux fois plus de crayons qu'Alya de livres. À elles trois, elles ont acheté un nombre pair de livres. Combien de crayons Bianca a-t-elle achetés ?","c":["2","4","6","7"],"a":1,"e":"Si Ivy a i livres : Alya a 2i crayons et 10 − 2i livres, Bianca 20 − 4i crayons et 4i − 10 livres. Total des livres = 3i, pair, avec 3 ≤ i ≤ 5 : i = 4, donc Bianca a 4 crayons.","o":"Sujet zéro 2026 · Q50"},{"id":312,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"À quel domaine artistique la « Nouvelle Vague » est-elle associée ?","c":["La peinture","Le cinéma","La musique","La sculpture"],"a":1,"e":"Courant du cinéma français de la fin des années 1950 (Godard, Truffaut, Chabrol, Rohmer).","o":"Annales 2021 · Q19"},{"id":313,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur du roman « Le Meilleur des mondes » ?","c":["George Orwell","Aldous Huxley","Ray Bradbury","H. G. Wells"],"a":1,"e":"Publié en 1932, ce roman d'anticipation décrit une société conditionnée. Orwell a écrit « 1984 », Bradbury « Fahrenheit 451 ».","o":"Annales 2021 · Q24"},{"id":314,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel écrivain a reçu le prix Goncourt 2021 pour « La plus secrète mémoire des hommes » ?","c":["Leïla Slimani","Mohamed Mbougar Sarr","Hervé Le Tellier","Alain Mabanckou"],"a":1,"e":"L'écrivain sénégalais Mohamed Mbougar Sarr a reçu le Goncourt 2021. Hervé Le Tellier l'avait obtenu en 2020 pour « L'Anomalie ».","o":"Annales 2022 · Q24"},{"id":315,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur du recueil « Les Fleurs du mal » ?","c":["Arthur Rimbaud","Paul Verlaine","Victor Hugo","Charles Baudelaire"],"a":3,"e":"Publié en 1857, le recueil vaut à Baudelaire un procès pour outrage à la morale publique.","o":"Annales 2022 · Q28"},{"id":316,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur de l'ouvrage « Le Capital » ?","c":["Adam Smith","John Maynard Keynes","Karl Marx","Friedrich Engels"],"a":2,"e":"Le livre I paraît en 1867 ; Engels publie les livres suivants après la mort de Marx.","o":"Annales 2023 · Q18"},{"id":317,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a réalisé le film « E.T. l'extra-terrestre » (1982) ?","c":["George Lucas","Steven Spielberg","James Cameron","Ridley Scott"],"a":1,"e":"Steven Spielberg a aussi réalisé « Les Dents de la mer » et « Jurassic Park ». George Lucas a créé « Star Wars ».","o":"Annales 2023 · Q22"},{"id":318,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel auteur de bande dessinée a créé la série « L'Arabe du futur » ?","c":["Joann Sfar","Marjane Satrapi","Enki Bilal","Riad Sattouf"],"a":3,"e":"Riad Sattouf y raconte son enfance entre la Libye, la Syrie et la France (six tomes, 2014-2022).","o":"Annales 2023 · Q24"},{"id":319,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a peint « La Joconde » ?","c":["Michel-Ange","Raphaël","Botticelli","Léonard de Vinci"],"a":3,"e":"Peinte au début du XVIe siècle, la Joconde est conservée au musée du Louvre ; Léonard de Vinci est mort en France, à Amboise, en 1519.","o":"Annales 2024 · Q18"},{"id":320,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel film a reçu la Palme d'or au Festival de Cannes 2023 ?","c":["Anatomie d'une chute","Titane","Sans filtre","Les Misérables"],"a":0,"e":"Réalisé par Justine Triet, troisième femme palmée ; « Titane » (Julia Ducournau) avait été récompensé en 2021.","o":"Annales 2024 · Q23"},{"id":321,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur du roman de science-fiction « Dune » ?","c":["Isaac Asimov","Frank Herbert","Philip K. Dick","Arthur C. Clarke"],"a":1,"e":"Paru en 1965, « Dune » a été adapté au cinéma par David Lynch (1984) puis Denis Villeneuve (2021 et 2024).","o":"Annales 2024 · Q26"},{"id":322,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur des « Misérables » (1862) ?","c":["Victor Hugo","Émile Zola","Eugène Sue","Honoré de Balzac"],"a":0,"e":"Écrit en grande partie pendant son exil à Guernesey, le roman suit Jean Valjean, Fantine, Cosette et Gavroche."},{"id":323,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel roman d'Émile Zola décrit une grève de mineurs dans le Nord ?","c":["Germinal","L'Assommoir","La Bête humaine","Nana"],"a":0,"e":"Publié en 1885, « Germinal » fait partie du cycle des Rougon-Macquart (20 romans)."},{"id":324,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Sous quel titre Honoré de Balzac a-t-il regroupé l'ensemble de ses romans ?","c":["La Recherche du temps perdu","La Comédie humaine","Les Thibault","Les Rougon-Macquart"],"a":1,"e":"« La Comédie humaine » rassemble près de 90 œuvres, dont « Le Père Goriot » et « Eugénie Grandet ». Les Rougon-Macquart sont de Zola."},{"id":325,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a écrit « Madame Bovary » (1857) ?","c":["Gustave Flaubert","George Sand","Stendhal","Guy de Maupassant"],"a":0,"e":"Comme Baudelaire la même année, Flaubert est poursuivi pour outrage aux bonnes mœurs, puis acquitté."},{"id":326,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a écrit « Le Rouge et le Noir » (1830) ?","c":["Prosper Mérimée","Alexandre Dumas","Alfred de Musset","Stendhal"],"a":3,"e":"Stendhal (Henri Beyle) y suit l'ascension de Julien Sorel ; il a aussi écrit « La Chartreuse de Parme »."},{"id":327,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur de la tragi-comédie « Le Cid » (1637) ?","c":["Jean Racine","Pierre Corneille","Molière","Jean Rotrou"],"a":1,"e":"La pièce déclenche la « querelle du Cid » ; Racine est l'auteur de « Phèdre », Molière du « Tartuffe »."},{"id":328,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel dramaturge a écrit « Le Tartuffe », « L'Avare » et « Le Misanthrope » ?","c":["Molière","Beaumarchais","Marivaux","Pierre Corneille"],"a":0,"e":"Jean-Baptiste Poquelin, dit Molière (1622-1673). Beaumarchais a écrit « Le Mariage de Figaro »."},{"id":329,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel auteur du XVIIe siècle a écrit « Le Corbeau et le Renard » ?","c":["Jean de La Bruyère","Nicolas Boileau","Jean de La Fontaine","Charles Perrault"],"a":2,"e":"Les Fables de La Fontaine (1668-1694) s'inspirent notamment d'Ésope. Perrault est l'auteur des « Contes »."},{"id":330,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a écrit « Le Petit Prince » (1943) ?","c":["Antoine de Saint-Exupéry","Joseph Kessel","Jules Verne","Romain Gary"],"a":0,"e":"Aviateur, Saint-Exupéry disparaît en mer en 1944 lors d'une mission de reconnaissance."},{"id":331,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel écrivain reçoit le prix Nobel de littérature en 1957 ?","c":["Albert Camus","Jean-Paul Sartre","François Mauriac","André Gide"],"a":0,"e":"Albert Camus, auteur de « L'Étranger » et de « La Peste ». Sartre refuse le Nobel en 1964."},{"id":332,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui est l'auteur d'« À la recherche du temps perdu » ?","c":["Louis-Ferdinand Céline","Romain Rolland","André Gide","Marcel Proust"],"a":3,"e":"Le deuxième volume, « À l'ombre des jeunes filles en fleurs », obtient le prix Goncourt en 1919."},{"id":333,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel écrivain a imaginé le capitaine Nemo et le Nautilus ?","c":["H. G. Wells","Victor Hugo","Alexandre Dumas","Jules Verne"],"a":3,"e":"« Vingt mille lieues sous les mers » paraît en 1869-1870 parmi les « Voyages extraordinaires »."},{"id":334,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a écrit « Les Trois Mousquetaires » ?","c":["Eugène Sue","Théophile Gautier","Paul Féval","Alexandre Dumas"],"a":3,"e":"Paru en 1844, le roman met en scène d'Artagnan, Athos, Porthos et Aramis. Dumas entre au Panthéon en 2002."},{"id":335,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel auteur de la Renaissance a écrit les « Essais » ?","c":["Michel de Montaigne","Pierre de Ronsard","François Rabelais","Joachim du Bellay"],"a":0,"e":"Montaigne, maire de Bordeaux, publie les « Essais » à partir de 1580. Rabelais a écrit « Gargantua »."},{"id":336,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a publié « Le Deuxième Sexe » en 1949 ?","c":["Élisabeth Badinter","Colette","Simone de Beauvoir","Marguerite Duras"],"a":2,"e":"Essai fondateur du féminisme : « On ne naît pas femme : on le devient. »"},{"id":337,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quelle écrivaine est la première femme élue à l'Académie française, en 1980 ?","c":["Marguerite Yourcenar","Marguerite Duras","Jacqueline de Romilly","Simone Veil"],"a":0,"e":"Auteure des « Mémoires d'Hadrien ». Jacqueline de Romilly est élue en 1988, Simone Veil en 2008."},{"id":338,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quelle écrivaine française a reçu le prix Nobel de littérature en 2022 ?","c":["Marie NDiaye","Maryse Condé","Leïla Slimani","Annie Ernaux"],"a":3,"e":"Annie Ernaux est la première Française lauréate du Nobel de littérature ; elle est l'auteure des « Années » et de « La Place »."},{"id":339,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel tableau de Claude Monet a donné son nom à l'impressionnisme ?","c":["Les Nymphéas","Le Déjeuner sur l'herbe","Impression, soleil levant","La Gare Saint-Lazare"],"a":2,"e":"Exposé en 1874, le tableau du port du Havre inspire au critique Louis Leroy le terme moqueur d'« impressionnistes ». « Le Déjeuner sur l'herbe » est de Manet."},{"id":340,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Qui a peint « La Liberté guidant le peuple » (1830) ?","c":["Jacques-Louis David","Gustave Courbet","Eugène Delacroix","Théodore Géricault"],"a":2,"e":"Le tableau célèbre les Trois Glorieuses de juillet 1830 ; il est conservé au Louvre. Géricault a peint « Le Radeau de la Méduse »."},{"id":341,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel sculpteur a réalisé « Le Penseur » ?","c":["Auguste Rodin","Camille Claudel","Antoine Bourdelle","Aristide Maillol"],"a":0,"e":"Conçu pour « La Porte de l'Enfer », le Penseur est visible au musée Rodin, à Paris."},{"id":342,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel compositeur français a écrit le « Boléro » (1928) ?","c":["Camille Saint-Saëns","Maurice Ravel","Claude Debussy","Erik Satie"],"a":1,"e":"Ravel compose ce ballet pour la danseuse Ida Rubinstein. Debussy a écrit « Clair de lune » et « La Mer »."},{"id":343,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel compositeur a écrit l'opéra « Carmen » (1875) ?","c":["Jules Massenet","Charles Gounod","Georges Bizet","Hector Berlioz"],"a":2,"e":"D'après une nouvelle de Prosper Mérimée. Gounod a écrit « Faust », Berlioz la « Symphonie fantastique »."},{"id":344,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quels frères organisent à Paris, en décembre 1895, la première projection publique et payante du cinématographe ?","c":["Les frères Goncourt","Les frères Pathé","Les frères Lumière","Les frères Montgolfier"],"a":2,"e":"Louis et Auguste Lumière projettent leurs films au Salon indien du Grand Café le 28 décembre 1895."},{"id":345,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel architecte a conçu la pyramide du Louvre, inaugurée en 1989 ?","c":["Le Corbusier","Ieoh Ming Pei","Renzo Piano","Jean Nouvel"],"a":1,"e":"L'architecte sino-américain I. M. Pei. Renzo Piano a conçu le Centre Pompidou avec Richard Rogers."},{"id":346,"m":"cg","t":"Arts, sciences et monde","s":"Arts et littérature","q":"Quel architecte est l'auteur de la Cité radieuse de Marseille ?","c":["Le Corbusier","Auguste Perret","Robert Mallet-Stevens","Jean Nouvel"],"a":0,"e":"Construite de 1947 à 1952, la Cité radieuse est inscrite au patrimoine mondial de l'Unesco avec 16 autres œuvres de Le Corbusier."},{"id":347,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Qu'est-ce qu'un réseau social ?","c":["Un site web ou une application pour acheter des produits en ligne","Un site web ou une application pour communiquer avec des amis et des connaissances","Un site web ou une application pour jouer en ligne","Un site web ou une application pour partager des photos"],"a":1,"e":"Un réseau social met en relation des utilisateurs qui échangent et partagent des contenus.","o":"Sujet zéro 2026 · Q19"},{"id":348,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Laurent veut connecter son smartphone à internet. Quel moyen peut-il utiliser ?","c":["La géolocalisation","La 3G/4G/5G","Le mode avion","L'accessibilité"],"a":1,"e":"Le réseau mobile (ou le wifi) donne accès à internet ; le mode avion coupe au contraire les connexions sans fil.","o":"Sujet zéro 2026 · Q20"},{"id":349,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Qu'est-ce qu'un virus informatique ?","c":["Un programme qui endommage l'ordinateur ou les données","Un programme qui protège l'ordinateur contre les virus","Un site web pour télécharger des logiciels","Un type de logiciel pour jouer en ligne"],"a":0,"e":"Un virus est un logiciel malveillant ; c'est l'antivirus qui protège l'ordinateur.","o":"Sujet zéro 2026 · Q21"},{"id":350,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Qu'est-ce qu'un cookie ?","c":["Un logiciel pour protéger l'ordinateur","Un petit fichier qui stocke des informations sur l'utilisateur","Un site web pour acheter des produits en ligne","Un type de virus informatique"],"a":1,"e":"Déposé par un site dans le navigateur, le cookie mémorise des préférences ou permet un suivi ; le RGPD impose le consentement.","o":"Sujet zéro 2026 · Q22"},{"id":351,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Qu'est-ce qu'un moteur de recherche ?","c":["Un logiciel pour protéger l'ordinateur","Un programme pour trouver des informations sur Internet","Un site web pour acheter des produits en ligne","Un type de virus informatique"],"a":1,"e":"Exemples : Google, Bing, Qwant, Ecosia.","o":"Sujet zéro 2026 · Q23"},{"id":352,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Le wifi et le Bluetooth fonctionnent par :","c":["des câbles","l'électricité statique","la fibre optique","des ondes"],"a":3,"e":"Ce sont des technologies sans fil utilisant des ondes radio.","o":"Sujet zéro 2026 · Q24"},{"id":353,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Que signifie l'acronyme MOOC ?","c":["Massive Open Online Course","Multiple Online Open Class","Mobile Open Online Content","Massive Online Organized Classroom"],"a":0,"e":"Un MOOC est un cours en ligne ouvert à tous, gratuit ou peu coûteux.","o":"Annales 2021 · Q30"},{"id":354,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quel os du corps humain est le fémur ?","c":["L'os du bras","L'os de la cuisse","L'os de la jambe, sous le genou","L'os de l'avant-bras"],"a":1,"e":"Le fémur, os de la cuisse, est l'os le plus long du corps humain. Le tibia et le péroné forment la jambe.","o":"Annales 2022 · Q19"},{"id":355,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quel pays est devenu en janvier 2024 le cinquième à réussir un alunissage ?","c":["L'Inde","La Corée du Sud","Israël","Le Japon"],"a":3,"e":"La sonde japonaise SLIM se pose le 20 janvier 2024, après l'URSS, les États-Unis, la Chine et l'Inde (2023).","o":"Annales 2024 · Q29"},{"id":356,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quel savant met au point le premier vaccin contre la rage, en 1885 ?","c":["Louis Pasteur","Claude Bernard","Albert Calmette","Robert Koch"],"a":0,"e":"Pasteur vaccine le jeune Joseph Meister. Calmette et Guérin ont mis au point le BCG contre la tuberculose."},{"id":357,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle scientifique est la première personne à recevoir deux prix Nobel dans deux disciplines scientifiques différentes ?","c":["Rosalind Franklin","Lise Meitner","Irène Joliot-Curie","Marie Curie"],"a":3,"e":"Marie Curie obtient le Nobel de physique (1903) puis celui de chimie (1911). Elle entre au Panthéon en 1995."},{"id":358,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"À quel chimiste français attribue-t-on la formule « Rien ne se perd, rien ne se crée, tout se transforme » ?","c":["Louis Pasteur","Joseph Gay-Lussac","Claude Berthollet","Antoine Lavoisier"],"a":3,"e":"Lavoisier, père de la chimie moderne, formule la loi de conservation de la masse ; il est guillotiné en 1794."},{"id":359,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle est la planète la plus proche du Soleil ?","c":["Mercure","Mars","Vénus","La Terre"],"a":0,"e":"Ordre des planètes : Mercure, Vénus, Terre, Mars, Jupiter, Saturne, Uranus, Neptune."},{"id":360,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle est la plus grande planète du système solaire ?","c":["Saturne","Uranus","Neptune","Jupiter"],"a":3,"e":"Jupiter, géante gazeuse, a une masse plus de deux fois supérieure à celle de toutes les autres planètes réunies."},{"id":361,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle est la formule chimique de l'eau ?","c":["H₂O₂","CO₂","H₂O","O₃"],"a":2,"e":"Deux atomes d'hydrogène et un d'oxygène. H₂O₂ est l'eau oxygénée, O₃ l'ozone, CO₂ le dioxyde de carbone."},{"id":362,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle est la vitesse approximative de la lumière dans le vide ?","c":["300 km/s","30 000 km/s","300 000 km/s","3 000 000 km/s"],"a":2,"e":"Exactement 299 792,458 km/s. La lumière du Soleil met environ 8 minutes à nous parvenir."},{"id":363,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Que désigne l'« hameçonnage » (phishing) ?","c":["Un programme qui affiche des publicités non sollicitées","Un logiciel qui chiffre les fichiers et réclame une rançon","Une technique visant à obtenir des données personnelles en se faisant passer pour un organisme de confiance","La saturation d'un site par un très grand nombre de requêtes"],"a":2,"e":"Faux message de la banque, des impôts ou d'un livreur. Le rançongiciel (ransomware) chiffre les fichiers ; l'attaque par déni de service sature un site."},{"id":364,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quel dispositif public permet d'accéder à plus de 1 000 services en ligne (impots.gouv.fr, ameli…) avec un compte existant ?","c":["Mon Espace Santé","La carte Vitale","FranceConnect","France Services"],"a":2,"e":"FranceConnect est le dispositif d'identification de l'État ; France Services désigne les guichets physiques d'accompagnement."},{"id":365,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Qu'est-ce que l'authentification à deux facteurs ?","c":["La possibilité de se connecter depuis deux appareils en même temps","Une vérification d'identité combinant deux éléments distincts, par exemple un mot de passe et un code reçu sur le téléphone","L'obligation de saisir deux fois le même mot de passe","L'utilisation d'un mot de passe d'au moins deux caractères spéciaux"],"a":1,"e":"Elle associe quelque chose que l'on sait, que l'on possède ou que l'on est (empreinte, visage)."},{"id":366,"m":"cg","t":"Arts, sciences et monde","s":"Sciences et numérique","q":"Quelle molécule porte l'information génétique des êtres vivants ?","c":["L'ATP","L'ADN","L'insuline","L'hémoglobine"],"a":1,"e":"L'acide désoxyribonucléique, dont la structure en double hélice est décrite en 1953 par Watson et Crick, avec les travaux de Rosalind Franklin."},{"id":367,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le nom de l'étendue d'eau qui borde la France à l'ouest ?","c":["La Manche","La mer Méditerranée","La mer du Nord","L'océan Atlantique"],"a":3,"e":"La France est bordée par la mer du Nord, la Manche, l'océan Atlantique et la Méditerranée.","o":"Sujet zéro 2026 · Q8"},{"id":368,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"En 2025, quel pays a le produit intérieur brut le plus élevé du monde ?","c":["L'Allemagne","Les États-Unis","Le Japon","La Russie"],"a":1,"e":"Les États-Unis devancent la Chine ; l'Allemagne est troisième.","o":"Sujet zéro 2026 · Q9"},{"id":369,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quelle est l'estimation de la population mondiale pour 2025 ?","c":["Entre 2 et 2,5 milliards d'habitants","Entre 4 et 4,5 milliards d'habitants","Entre 6 et 6,5 milliards d'habitants","Entre 8 et 8,5 milliards d'habitants"],"a":3,"e":"Selon l'ONU, la population mondiale a dépassé 8 milliards en novembre 2022.","o":"Sujet zéro 2026 · Q10"},{"id":370,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel facteur conduit à l'urbanisation ?","c":["L'exode rural","L'exode urbain","L'industrialisation","Le tourisme"],"a":0,"e":"Corrigé officiel : l'exode rural, c'est-à-dire le départ des habitants des campagnes vers les villes.","o":"Sujet zéro 2026 · Q12"},{"id":371,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Dans quel océan se trouve l'archipel de Saint-Pierre-et-Miquelon ?","c":["L'océan Atlantique","L'océan Pacifique","L'océan Indien","L'océan Arctique"],"a":0,"e":"L'archipel est situé au large de Terre-Neuve (Canada).","o":"Annales 2022 · Q22"},{"id":372,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Avec combien de pays la France métropolitaine partage-t-elle une frontière terrestre ?","c":["5","6","7","8"],"a":3,"e":"Belgique, Luxembourg, Allemagne, Suisse, Italie, Monaco, Andorre et Espagne.","o":"Annales 2024 · Q19"},{"id":373,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le point culminant de la France ?","c":["Le mont Blanc","La Barre des Écrins","Le pic du Midi de Bigorre","Le mont Cervin"],"a":0,"e":"Le mont Blanc culmine à environ 4 806 m, à la frontière franco-italienne. Le Cervin est en Suisse et en Italie."},{"id":374,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le plus long fleuve entièrement français ?","c":["La Garonne","La Loire","La Seine","Le Rhône"],"a":1,"e":"La Loire mesure environ 1 000 km et se jette dans l'Atlantique à Saint-Nazaire. Le Rhône prend sa source en Suisse."},{"id":375,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Dans quelle mer se jette la Seine ?","c":["La Manche","La mer du Nord","L'océan Atlantique","La mer Celtique"],"a":0,"e":"La Seine se jette dans la Manche entre Le Havre et Honfleur."},{"id":376,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Avec quels pays la Guyane partage-t-elle ses frontières terrestres ?","c":["Le Brésil et le Venezuela","Le Suriname et le Guyana","Le Brésil et le Suriname","La Colombie et le Brésil"],"a":2,"e":"Frontière avec le Brésil (le long de l'Oyapock) et le Suriname (le long du Maroni) ; c'est la plus longue frontière terrestre de la France."},{"id":377,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le chef-lieu de La Réunion ?","c":["Le Port","Saint-Denis","Saint-Pierre","Saint-Paul"],"a":1,"e":"Saint-Denis est la préfecture de La Réunion, île de l'océan Indien."},{"id":378,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le point culminant du Massif central ?","c":["Le puy de Sancy","Le puy de Dôme","Le mont Lozère","Le Plomb du Cantal"],"a":0,"e":"Le puy de Sancy culmine à 1 885 m ; le puy de Dôme à 1 465 m."},{"id":379,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quelle est la capitale de l'Australie ?","c":["Canberra","Perth","Sydney","Melbourne"],"a":0,"e":"Canberra a été choisie en 1908 comme compromis entre Sydney et Melbourne."},{"id":380,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quelle est la capitale du Canada ?","c":["Vancouver","Toronto","Montréal","Ottawa"],"a":3,"e":"Ottawa est située dans l'Ontario, près de la frontière avec le Québec."},{"id":381,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le plus grand désert chaud du monde ?","c":["Le désert d'Arabie","Le désert de Gobi","Le Kalahari","Le Sahara"],"a":3,"e":"Le Sahara couvre environ 9 millions de km². Les déserts polaires (Antarctique) sont plus vastes."},{"id":382,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le plus vaste océan du globe ?","c":["L'océan Austral","L'océan Pacifique","L'océan Indien","L'océan Atlantique"],"a":1,"e":"Le Pacifique couvre environ un tiers de la surface terrestre."},{"id":383,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel pays est devenu le plus peuplé du monde en 2023, selon l'ONU ?","c":["La Chine","L'Inde","Le Pakistan","L'Indonésie"],"a":1,"e":"L'Inde dépasse la Chine en 2023, avec plus de 1,4 milliard d'habitants."},{"id":384,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quelle est approximativement la population de la France (métropole et outre-mer) au 1er janvier 2025, selon l'Insee ?","c":["59 millions","64 millions","69 millions","74 millions"],"a":2,"e":"L'Insee estime la population à environ 68,6 millions d'habitants au 1er janvier 2025."},{"id":385,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quelle est la troisième ville la plus peuplée de France (commune) ?","c":["Lyon","Toulouse","Nice","Lille"],"a":0,"e":"Paris, Marseille, Lyon, puis Toulouse et Nice."},{"id":386,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Dans quel département se trouve Giverny, où Claude Monet a peint les « Nymphéas » ?","c":["Le Val-d'Oise","Le Calvados","L'Eure","Les Yvelines"],"a":2,"e":"Monet vit à Giverny (Eure, Normandie) de 1883 à sa mort en 1926."},{"id":387,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel détroit sépare l'Europe de l'Afrique ?","c":["Le détroit du Bosphore","Le pas de Calais","Le détroit de Gibraltar","Le détroit de Messine"],"a":2,"e":"Large d'environ 14 km, il relie la Méditerranée à l'Atlantique. Le Bosphore sépare l'Europe de l'Asie."},{"id":388,"m":"cg","t":"Arts, sciences et monde","s":"Géographie","q":"Quel est le plus long fleuve d'Europe ?","c":["Le Dniepr","Le Rhin","Le Danube","La Volga"],"a":3,"e":"La Volga (environ 3 500 km) coule en Russie et se jette dans la mer Caspienne ; le Danube (2 850 km) est le deuxième."},{"id":389,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"En quelle année George Washington est-il devenu le premier président des États-Unis ?","c":["1689","1789","1889","1989"],"a":1,"e":"George Washington prête serment le 30 avril 1789, quelques jours avant l'ouverture des états généraux en France.","o":"Sujet zéro 2026 · Q5"},{"id":390,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel pays a accueilli la 30e Conférence des Parties (COP 30) en 2025 ?","c":["Le Brésil","La Chine","Les États-Unis","La France"],"a":0,"e":"La COP 30 s'est tenue à Belém, en Amazonie brésilienne, en novembre 2025.","o":"Sujet zéro 2026 · Q25"},{"id":391,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel pays a augmenté, au cours de l'année 2025, ses droits de douane vis-à-vis de nombreux pays du monde ?","c":["Les États-Unis","La France","La Russie","L'Ukraine"],"a":0,"e":"L'administration Trump a relevé ses droits de douane sur de nombreux partenaires commerciaux, dont l'Union européenne.","o":"Sujet zéro 2026 · Q26"},{"id":392,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Au cours de 2025, quel pays a élu une femme comme Premier ministre pour la première fois ?","c":["L'Allemagne","La France","L'Italie","Le Japon"],"a":3,"e":"Sanae Takaichi devient en octobre 2025 la première femme Première ministre du Japon. La France (Édith Cresson, 1991) et l'Italie (Giorgia Meloni, 2022) l'avaient déjà fait.","o":"Sujet zéro 2026 · Q27"},{"id":393,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quels sont les deux Premiers ministres qui se sont succédé en France en 2025 ?","c":["François Bayrou et Sébastien Lecornu","Jean Castex et Élisabeth Borne","Édouard Philippe et Bernard Cazeneuve","Manuel Valls et Jean-Marc Ayrault"],"a":0,"e":"François Bayrou est nommé en décembre 2024 ; Sébastien Lecornu lui succède en septembre 2025.","o":"Sujet zéro 2026 · Q28"},{"id":394,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quelle maladie a affecté les élevages bovins en 2025 ?","c":["La dermatose nodulaire contagieuse","La fièvre catarrhale ovine","La fièvre porcine africaine","La grippe aviaire"],"a":0,"e":"Apparue en Savoie en juin 2025, la dermatose nodulaire contagieuse a entraîné vaccinations et abattages.","o":"Sujet zéro 2026 · Q29"},{"id":395,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Dans quel pays a été créée l'application TikTok ?","c":["Les États-Unis","La Chine","Le Japon","La Corée du Sud"],"a":1,"e":"TikTok appartient à l'entreprise chinoise ByteDance ; sa version chinoise s'appelle Douyin.","o":"Annales 2021 · Q17"},{"id":396,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Qui a remporté le Vendée Globe 2020-2021 ?","c":["Charlie Dalin","Jean Le Cam","Louis Burton","Yannick Bestaven"],"a":3,"e":"Arrivé deuxième, Charlie Dalin est classé derrière Yannick Bestaven après les bonifications accordées pour le sauvetage de Kevin Escoffier.","o":"Annales 2021 · Q29"},{"id":397,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Qui a succédé à Angela Merkel comme chancelier fédéral d'Allemagne en décembre 2021 ?","c":["Armin Laschet","Friedrich Merz","Olaf Scholz","Frank-Walter Steinmeier"],"a":2,"e":"Olaf Scholz (SPD) est chancelier de 2021 à 2025 ; Friedrich Merz lui succède en mai 2025. Steinmeier est président fédéral.","o":"Annales 2022 · Q23"},{"id":398,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Qui est considéré comme le rénovateur des Jeux olympiques modernes ?","c":["Pierre de Coubertin","Jules Rimet","Jacques Rogge","Avery Brundage"],"a":0,"e":"Pierre de Coubertin fonde le CIO en 1894 ; les premiers Jeux modernes ont lieu à Athènes en 1896. Jules Rimet a créé la Coupe du monde de football.","o":"Annales 2024 · Q20"},{"id":399,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel pays organisera les Jeux olympiques d'hiver de 2030 ?","c":["L'Italie","La France","La Suisse","La Suède"],"a":1,"e":"Les Jeux de 2030 auront lieu dans les Alpes françaises (Auvergne-Rhône-Alpes et Provence-Alpes-Côte d'Azur). L'Italie a accueilli ceux de 2026.","o":"Annales 2025 · Q28"},{"id":400,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quelle température est recommandée dans les pièces à vivre d'un logement chauffé ?","c":["22 °C","21 °C","20 °C","19 °C"],"a":3,"e":"Le Code de l'énergie et le plan de sobriété retiennent 19 °C ; chaque degré en moins réduit la consommation d'environ 7 %.","o":"Annales 2025 · Q29"},{"id":401,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quelle ville a accueilli les Jeux olympiques d'été de 2024 ?","c":["Paris","Tokyo","Londres","Los Angeles"],"a":0,"e":"Paris accueille les JO pour la troisième fois, après 1900 et 1924. Los Angeles accueillera ceux de 2028."},{"id":402,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"En quelle année tombe le mur de Berlin ?","c":["1961","1985","1989","1991"],"a":2,"e":"Le mur, construit en 1961, tombe le 9 novembre 1989 ; l'Allemagne est réunifiée le 3 octobre 1990 et l'URSS disparaît fin 1991."},{"id":403,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Dans quelle ville est signée la Charte des Nations unies en juin 1945 ?","c":["San Francisco","Yalta","New York","Genève"],"a":0,"e":"Signée le 26 juin 1945, elle entre en vigueur le 24 octobre 1945. Le siège de l'ONU est ensuite installé à New York."},{"id":404,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Dans quel lieu de Paris est adoptée la Déclaration universelle des droits de l'homme en 1948 ?","c":["Au palais de Chaillot","Au palais du Luxembourg","Au palais des Congrès","Au palais de l'Élysée"],"a":0,"e":"Adoptée le 10 décembre 1948 par l'Assemblée générale de l'ONU ; le juriste français René Cassin a participé à sa rédaction."},{"id":405,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Qui est le premier homme à marcher sur la Lune, en juillet 1969 ?","c":["Buzz Aldrin","Youri Gagarine","Neil Armstrong","Michael Collins"],"a":2,"e":"Mission Apollo 11. Buzz Aldrin le suit ; Michael Collins reste en orbite. Gagarine est le premier homme dans l'espace (1961)."},{"id":406,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"En quelles années l'équipe de France masculine de football a-t-elle remporté la Coupe du monde ?","c":["1984 et 2000","1998 et 2018","1998 et 2006","2002 et 2018"],"a":1,"e":"Victoire contre le Brésil en 1998 (3-0), puis contre la Croatie en 2018 (4-2). En 2006, la France perd la finale contre l'Italie."},{"id":407,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel dirigeant sud-africain, emprisonné pendant 27 ans, devient président en 1994 ?","c":["Nelson Mandela","Thabo Mbeki","Frederik de Klerk","Desmond Tutu"],"a":0,"e":"Prix Nobel de la paix en 1993 avec Frederik de Klerk, Nelson Mandela est le premier président noir d'Afrique du Sud."},{"id":408,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel pays a annexé la Crimée en 2014 ?","c":["L'Ukraine","La Russie","La Turquie","La Biélorussie"],"a":1,"e":"L'annexion par la Russie, en mars 2014, n'est pas reconnue par la communauté internationale.","o":"Annales 2023 · Q17"},{"id":409,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel nageur français a remporté quatre médailles d'or individuelles aux Jeux olympiques de Paris 2024 ?","c":["Maxime Grousset","Yannick Agnel","Florent Manaudou","Léon Marchand"],"a":3,"e":"Léon Marchand gagne le 200 m papillon, le 200 m brasse, le 200 m et le 400 m quatre nages."},{"id":410,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quelle cathédrale parisienne, endommagée par un incendie en 2019, rouvre ses portes en décembre 2024 ?","c":["La Sainte-Chapelle","La basilique du Sacré-Cœur","La basilique de Saint-Denis","Notre-Dame de Paris"],"a":3,"e":"Notre-Dame rouvre le 7 décembre 2024, un peu plus de cinq ans après l'incendie du 15 avril 2019."},{"id":411,"m":"cg","t":"Arts, sciences et monde","s":"Monde, sport et actualité","q":"Quel président américain est entré en fonctions pour un second mandat non consécutif en janvier 2025 ?","c":["George W. Bush","Joe Biden","Barack Obama","Donald Trump"],"a":3,"e":"Donald Trump, déjà président de 2017 à 2021, est le deuxième président à exercer deux mandats non consécutifs, après Grover Cleveland."}]};
